quests[59897] = { id = 59897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Baron", description = "Nehmt dieses Amulett. Jeder der Vier Reiter trägt so eines.\n\nDie Amulette sind mit einer Macht versehen, die sie miteinander verbindet. Diese Verbindung sollte Euch dabei helfen, Darion Mograine zu finden.\n\nDarion hat zweifellos zahllose Schrecken im Schlund miterlebt. Vielleicht hat er den verschollenen Baron gesehen.\n\nHoffen wir, dass er Euch auch zu unseren Verbündeten aus Azeroth führen kann.", sourceObjective = "Betretet den Schlund.", sourceObjectiveStatus = "unverified-source-field" }
quests[59902] = { id = 59902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unverhoffter Schatz" }
quests[59903] = { id = 59903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Split Blob Test" }
quests[59904] = { id = 59904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unverhoffter Schatz" }
