quests[59907] = { id = 59907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlundgebundene Bedrohung", description = "Unsere Ritter sind stark, aber in so geringer Zahl haben sie keine Chance gegen diesen Feind.\n\nWir müssen die feindlichen Reihen ausdünnen. Die Truppen der Schwarzen Klinge helfen uns nichts, wenn sie alle tot sind.", sourceObjective = "Besiegt 8 schlundgebundene Feinde im Tiegel der Verdammten.", completion = "Unsere Feinde sind unerbittlich, aber wir werden sie zurückschlagen.\n\nBleibt standhaft, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59910] = { id = 59910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen und Kämpfen", description = "Mograine und Emeni werden den Angriff auf das westliche Tor anführen.\n\nIhr und Xandria werdet von Osten her angreifen. Sichert das Gebiet und eliminiert jeglichen Widerstand.\n\nSobald wir sie umzingelt haben, können wir Gharmal den Todesstoß versetzen.", sourceObjective = "Fliegt mit Xandria zum Haus der Konstrukte.", completion = "Dieser Ort ist vom Grauen befleckt. Wir müssen ihn läutern.", sourceObjectiveStatus = "unverified-source-field" }
quests[59914] = { id = 59914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schritt nicht wagen", description = "Es scheint, als wären wir dem Feind fürs Erste entkommen. Wir sollten die Gelegenheit nutzen und dieses Gebiet nach Spuren unserer Verbündeten absuchen.\n\nAllein erregen wir weniger Aufmerksamkeit. Die Schwarze Klinge bleibt in Stellung und wartet auf mein Zeichen.\n\nKommt, sehen wir mal, was uns in dieser Hölle alles erwartet.", sourceObjective = "Durchkämmt Calcis nach Hinweisen auf Eure Verbündeten.", progress = "Champion? Sagt mir, dass das keine Illusion ist.", completion = "Gelobt sei das Licht! Ich... ich hatte schon fast alle Hoffnung aufgegeben.\n\n<Jainas Blick schweift über die Ritter der Schwarzen Klinge.>\n\nIst das... alles, was von Euren Truppen übrig ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[59915] = { id = 59915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele in der Hand", description = "Mein Instinkt war richtig. Welch dunkle Magie diese Seelen auch aneinander fesselt, hält sie auch einigermaßen kohärent.\n\nEs wird etwas dauern, aber wir finden schon heraus, was dieses Ding weiß. Für mein Verhör benötige ich den Helm. Anschließend gebe ich ihn Euch zurück. Ihr habt mein Wort.\n\nDann bringen wir unseren Schatz mal zur Lordadmiralin.", sourceObjective = "Kehrt zu Lady Jaina Prachtmeer in die Trostlose Rast zurück.", completion = "Anscheinend war Eure Suche von Erfolg gekrönt.\n\nGenug ausgeruht. Es gibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[59916] = { id = 59916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlächter der Bastion", description = "Haben diese Scheusale meinem Volk Gnade gezeigt, als sie die Bastion angegriffen haben? Als sie meine Brüder und Schwestern auseinandergerissen und benutzt haben, um noch mehr von diesen... Monstren zu erschaffen?!\n\nNein! Die Schlächter der Bastion haben an diesem Tag ihre Absichten offenbart!\n\nSie verdienen nichts anderes als die ewige Finsternis, die auf sie wartet. Sorgt dafür, dass sie sie erleben werden!", sourceObjective = "Tötet 10 Truppen des Hauses der Konstrukte in der Auftrennungskammer.", completion = "Dieses Blutvergießen wird sie nicht zurückbringen... aber es könnte anderen das gleiche Schicksal ersparen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59917] = { id = 59917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie müssen sterben", description = "Diese hirnlosen Monstrositäten stammen aus den entlegensten Winkeln der Schattenlande. Die Animadürre hat ihren unersättlichen Hunger geschürt und sie dazu getrieben, neue Quellen zu suchen.\n\nIhre Anwesenheit hier ist, gelinde gesagt, lästig.\n\nSie zerreißen das Land auf der Suche nach aller Anima, die sie finden können. Wir müssen sie dezimieren und Zeit gewinnen, um das in dem Grabmal eingeschlossene Wissen zu sichern.\n\nGenau die Art von Arbeit, die Ihr gewohnt seid, ja?", sourceObjective = "Tötet 8 wütende Vielfraße.", completion = "Gut gemacht. Ihr habt uns wertvolle Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[59919] = { id = 59919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verdientes Band", description = "Eine Sache noch, <Schlundgänger/Schlundgängerin>.\n\nMit dem Zusammensetzen des Emblems des Aufstiegs habt Ihr mehr als nur das Vertrauen der anderen Kyrianer verdient. Anscheinend hat unser Oberster Schmied Mikanikos die gemeinsame Zeit mit Euch genossen und möchte ein Seelenband mit Euch eingehen.\n\nDa er sich eher selbst am nächsten steht, bin ich genauso überrascht wie Ihr. Ihr müsst ihn sehr beeindruckt haben.", sourceObjective = "Geht ein Seelenband mit Mikanikos ein.", completion = "Nicht in all meinen Jahrtausenden hätte ich gedacht, dass einmal ein Provost ein Seelenband mit einem Fremden eingeht. Die Zeiten ändern sich ganz offensichtlich, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[59920] = { id = 59920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzündet die Schmiede", description = "Ich glaube, wir haben endlich die Materialien, die ich für das Anfeuern der Schmiede benötige.\n\nIch fürchte, sie ist in ziemlich baufälligem Zustand. Nach mehrfach gescheiterten Versuchen, ohne Anima zu arbeiten, und schlichter Vernachlässigung kann ich nicht darauf hoffen, sie in diesem Zustand zu benutzen.\n\nIch würde es wirklich sehr zu schätzen wissen, wenn Ihr mir helft, indem Ihr hier Ordnung schafft, während ich die Schmiede erneut dazu überrede, zum Leben zu erwachen.", sourceObjective = "Helft Schmiedin Sophone.", completion = "Ich bin für Eure Hilfe äußerst dankbar. Jetzt kann ich wieder meinem Handwerk nachgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59921] = { id = 59921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was ich jemals sein werde", description = "Das ist der Schauplatz einer alten Schlacht, die das ehemalige Paragon des Mutes gewann. Sie hat sich selbst geopfert, um den Schattenlanden zu dienen. Ich kann nur hoffen, das mein Ende ein ebenso gutes Beispiel wird.\n\nViele meiner Schüler sinnen über die Schriftrollen hier nach. So gedenken wir des Fundaments unseres Mutes.\n\nBegleitet Alexandros, während er über seine Schreine reflektiert. Helft ihm zu ergründen, wo der Ursprung seines Mutes liegt.\n\nEr wird erfahren, dass dieses Jenseits nicht das passende für ihn ist.", sourceObjective = "Reflektiert mit Alexandros Mograine über die Schriftrollen der Erinnerung.", progress = "Was habt Ihr erfahren?", completion = "Hat dieses Unterfangen Euch erleuchtet?", sourceObjectiveStatus = "unverified-source-field" }
quests[59922] = { id = 59922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht vergessen", description = "Das Urteil der Richterin war untrüglich wie immer.\n\nObwohl Alexandros' Hingabe zum Licht nicht zu leugnen ist, bezieht er seine Kraft in Wahrheit hauptsächlich aus der Erinnerung an die, die ihm nahestanden. Er gehört nach Maldraxxus und nicht in die Bastion.\n\nNichtsdestotrotz haben wir den Tempel zurückgewonnen. Meine Rache ist noch nicht vollends geübt, aber jetzt weiß ich, dass ich einigen Maldraxxi noch trauen kann.\n\nGeht nun. Kehrt mit der Kunde des heutigen Sieges zu Eurer Anführerin zurück.\n\nUnd morgen löschen wir unsere Feinde ein für alle Mal aus.", sourceObjective = "Kehrt zu Draka im Sitz des Primus zurück.", completion = "Wir haben also unsere Ehre bewiesen... und einen neuen Verbündeten gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59926] = { id = 59926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwärmen", description = "Wir nähern uns der Insel, auf der die letzte Expedition der Horde verschwunden ist.\n\nIhr müsst auf alles vorbereitet sein, was da draußen warten könnte. Wärmt Euch mit diesen Kampfattrappen auf.", sourceObjective = "Wärmt Euch ein wenig an der Kampfattrappe auf.", progress = "Belästigt mich nicht! Geht und greift diese Kampfattrappen an. Zeigt mir Eure Kraft.", completion = "Gut. Ihr habt geübt, seit wir aufgebrochen sind.\n\nIch muss mit der Besatzung über diesen Sturm reden. \n\nÜbt mit Throg. Er wird Eure Fähigkeiten einschätzen und Eure Rolle festlegen, sobald wir anlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59927] = { id = 59927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standhalten", description = "Lok-tar! Nichts schlägt einen guten Kampf im Regen. \n\nWir werden üben und Eure Kräfte messen!", sourceObjective = "Tragt einen Übungskampf gegen Grunzer Throg aus.", completion = "Ihr seid ein vielversprechender {class}. Vielleicht werdet auch Ihr Ruhm auf der Insel finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[59928] = { id = 59928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsicht, Einschlag!", description = "Gut gekämpft, {name}. Ihr bringt der Horde Kraft und Ehre!\n\nJetzt werden wir einfach... Wartet...\n\nHabt Ihr das gehört?", sourceObjective = "Findet Kriegsherrin Breka.", completion = "Dieses Schiff wird es nicht unversehrt zur Insel schaffen.\n\nHaltet Euch an irgendetwas fest und betet, dass die Elemente uns einen grauenhaften Tod auf See ersparen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59929] = { id = 59929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocmanie", description = "Das Ufer ist von Schiffswracks gesäumt. Hier muss die verlorene Expedition gestrandet sein.\n\nWir brauchen mehr Vorräte, damit die Verwundeten wieder genesen können. Die Murlocs in der Nähe haben den Großteil dessen gestohlen, was angespült worden ist.\n\nTötet diese Murlocs und holt zurück, was der Horde gehört.", sourceObjective = "Holt 6 Erste-Hilfe-Kästen von Murlocs zurück.", progress = "Die Murlocs haben unsere Erste-Hilfe-Kästen. Tötet sie und bringt alle Kästen zu mir.", completion = "Ausgezeichnete Arbeit. Helfen wir den Überlebenden, wieder auf die Beine zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59930] = { id = 59930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Erste Hilfe", description = "Wir müssen unsere Verwundeten versorgen, bevor wir uns aufmachen können, um die verschwundene Expedition zu suchen.\n\nNehmt diesen Erste-Hilfe-Kasten und kümmert Euch um die Überlebenden. Ich übernehme die anderen in der Nähe.", sourceObjective = "Benutzt den Erste-Hilfe-Kasten bei Bo, Mithdran Dämmersucher und Lana Jordan.", progress = "Benutzt Euren Erste-Hilfe-Kasten, um den anderen zu helfen.", completion = "Es geht uns allen besser. Machen wir uns auf den Weg. Die verschollene Expedition ist irgendwo auf dieser Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[59931] = { id = 59931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach der verschollenen Expedition", description = "Breka Grimmaxt ist nach Norden gegangen, um Überlebende zu suchen. Schließt Euch ihr an und seht, was sie gefunden hat.\n\nIch gehe vor, um zu sehen, ob ich noch jemanden finde. Wir treffen uns weiter im Inneren der Insel wieder.", sourceObjective = "Durchsucht das nahe Lager nach Überlebenden der Expedition.", completion = "So... hungrig...\n\nSie ham... alle andren mitgenomm'n... Ich bin... die Letzte...", sourceObjectiveStatus = "unverified-source-field" }
quests[59932] = { id = 59932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grillfleisch", description = "Das ist Won'sa, eine Schamanin der Expedition.\n\nSie verhungert. So darf kein Mitglied der Horde sterben!\n\nTötet ein paar Wildtiere in der Nähe und kocht ihr Fleisch über dem Feuer.\n\nWon'sa kann uns erzählen, was mit der verschollenen Expedition geschehen ist, nachdem sie gegessen hat.", sourceObjective = "Beschafft 5 Stücke rohes Fleisch von Wildtieren um das verlassene Lager und bereitet es am Lagerfeuer zu.", progress = "Bitte... ich brauch... Essen...", completion = "<Won'sa isst schnell das Fleisch, das Ihr zubereitet habt.>\n\nSieht so aus, als ob ich doch noch nich' zu Bwonsamdi geh'n werde.\n\nIhr solltet Euch beeil'n. Die Stacheleber ham Shuja und den Rest der Expedition verschleppt!", sourceObjectiveStatus = "unverified-source-field" }
quests[59933] = { id = 59933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftechniken für Fortgeschrittene", description = "Won'sa hat gesagt, die Stacheleber hätten die vermisste Expedition verschleppt... einschließlich meiner Tochter.\n\nDie Stacheleber werden Euch töten, wenn Ihr nicht vorbereitet seid. Sie sind viel schlauer und tödlicher als Murlocs.\n\nIch will Euch nicht durch ihre Hände sterben sehen. Wir werden einen letzten Übungskampf durchführen.\n\nWenn wir fertig sind, werdet Ihr einen Schneise durch die Stacheleber schlagen!", sourceObjective = "Führt mit Kriegsherrin Grimmaxt einen Übungskampf durch.", completion = "Ihr seid bereit, die Stacheleber abzuschlachten! Wir sollten mit Won'sa sprechen, um herauszufinden, was sie weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[59934] = { id = 59934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftechniken für Fortgeschrittene", description = "Won'sa hat gesagt, die Stacheleber hätten die vermisste Expedition verschleppt... einschließlich meiner Tochter.\n\nDie Stacheleber werden Euch töten, wenn Ihr nicht vorbereitet seid. Sie sind viel schlauer und tödlicher als Murlocs.\n\nIch will Euch nicht durch ihre Hände sterben sehen. Wir werden einen letzten Übungskampf durchführen.\n\nWenn wir fertig sind, werdet Ihr einen Schneise durch die Stacheleber schlagen!", sourceObjective = "Führt mit Kriegsherrin Grimmaxt einen Übungskampf durch.", completion = "Ihr seid bereit, die Stacheleber abzuschlachten! Wir sollten mit Won'sa sprechen, um herauszufinden, was sie weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[59935] = { id = 59935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nordwärts", description = "Die Stacheleber ham den Rest der Expedition verschleppt und nach Norden gebracht.\n\nSie ham davon geredet, sie für irgend'n Opfer zu benutz'n!\n\nIhr müsst so schnell wie möglich nach Norden geh'n, um sie aufzuhalt'n!", sourceObjective = "Seht Euch weiter nördlich nach Mithdran Dämmersucher um.", completion = "Ich habe gute Nachrichten... und weniger gute.", sourceObjectiveStatus = "unverified-source-field" }
quests[59937] = { id = 59937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebändigte Wildnis", description = "<Ein Jäger/Eine Jägerin> wie Ihr braucht ein gutes Tier an der Seite. Habt Ihr keines mitgebracht?\n\nHmm. Dann muss ich wohl Euren Mangel an Übung ausgleichen.\n\nHört gut zu und lernt schnell. Ich werde Euch zeigen, wie Ihr ein Tier zähmen und zu Eurem Begleiter machen könnt.\n\nIhr werdet einen brauchen, wenn Ihr gegen die Stacheleber kämpfen wollt.", sourceObjective = "Lernt von Mithdran Dämmersucher, wie man Wildtiere zähmt. Setzt dann 'Wildtier zähmen' bei einem Tier in der Nähe ein.", completion = "Gute Arbeit. Die Lektionen, die Ihr vom unvergleichlichen Mithdran Dämmersucher lernt, werden Euch ein Leben lang nützen.\n\nUnd was nun die Sache mit unseren Stachelebergegnern angeht...", sourceObjectiveStatus = "unverified-source-field" }
quests[59938] = { id = 59938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit den Stachelebern", description = "Ich habe entdeckt, dass die Stacheleber ein nekrotisches Ritual an einem Überlebenden der verschollenen Expedition durchführen.\n\nDer Anführer des Stammes, Geofürst Grek'og, führt das Ritual aus.\n\nTötet Grek'og und rettet den Überlebenden.\n\nZeigt diesem Grobian, dass man sich nicht mit der Horde anlegen sollte.", sourceObjective = "Tötet Geofürst Grek'og.", completion = "Ihr habt wirklich Mumm, das respektiere ich. Ich habe mich dieser Expedition angeschlossen, weil ich dachte, ich könnte schnell und einfach ein wenig Profit machen.\n\nAber jetzt mit der ganzen Nekromantie und den verrückten Ogern... Vielleicht kann ich VIEL Profit machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59939] = { id = 59939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Nekromantie der Stacheleber", description = "Stacheleber sind wild und gewalttätig. Ich dachte, Nekromantie wäre ihnen zu hoch.\n\nWir müssen ihre Rituale natürlich aufhalten. Sie dürfen sie auf keinen Fall an Mitgliedern der Horde ausführen.\n\nTötet die Stacheleber im Höhlenbau. Sie müssen ihren tragischen Fehler spüren.", sourceObjective = "Tötet 7 Stacheleber im Dornendickicht der Stacheleber.", completion = "Sehr gute Arbeit. Die Stacheleber scheinen jetzt Abstand zu halten. Vielleicht haben sie ihre Lektion gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59940] = { id = 59940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Turboholperer Mk. 5", description = "Ihr habt Glück, denn ich bin der EINZIGE Goblin, der Euch helfen kann, den Rest der Expedition zu finden!\n\nSchaut Euch mal dieses raffinierte Gerät an. Hab es einem Gnom gestohlen, aufgepeppt und etwas Eigenes daraus gemacht!\n\nIch nenne es den Turboholperer Mk. 5. Benutzt ihn, um Shuja und die anderen zu finden.", sourceObjective = "Benutzt den Turboholperer Mk. 5, um Shuja Grimmaxt zu finden.", progress = "Was redet Ihr auf mich ein? Springt auf den Turboholperer Mk. 5 auf und los!", completion = "Also schön, Zeit, die Regeln zu beugen und einen Rieseneber zu machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59941] = { id = 59941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Probleme brauchen größere Lösungen", description = "Ich nenne dieses Ding \"den Größenänderer\". Ich habe ihn benutzt, um den Turboholperer Mk. 5 zu entschrumpfen.\n\nAlso, ich will ehrlich sein. Ich habe bestenfalls ein flüchtiges Verständnis davon, wie dieses Ding funktioniert.\n\nDas heißt, ich werde eine Menge Knöpfe drücken, um zu sehen, was passiert.\n\nIch bin sicher, wir finden heraus, wie man einen dieser Eber größer machen kann. Dann benutzen wir den, um diese Untoten niederzutrampeln!\n\nIhr haltet den Größenänderer, während ich daran herumtüftele. Dann nur noch auf den Knopf drücken und, äh... auf das Beste hoffen?", sourceObjective = "Setzt den Größenänderer bei 3 wandernden Ebern ein.", progress = "Zeigt bloß nicht mit dem Größenänderer auf mich, verstanden? Benutzt ihn bei den Ebern.", completion = "Der Rieseneber war also vergebliche Mühe und Ihr habt stattdessen dieses Gerät zu einer Waffe gemacht?\n\nGute Arbeit. Dann wollen wir mal sehen, ob Ihr das hinbekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59942] = { id = 59942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lebendigkeitsänderer", description = "Ich habe den perfekten Plan. Ihr werdet im Turboholperer Mk. 5 mitfliegen und diese laufenden Kadaver vom Himmel aus IN DIE LUFT JAGEN!\n\nHiermit taufe ich den Größenänderer auf \"Lebendigkeitsänderer\" um. Wir werden ihnen zeigen, wo die Untoten hingehören!\n\nÄh, außer natürlich UNSERE Untoten. Die sind vollkommen in Ordnung.\n\nWie auch immer, steigt in den Turboholperer Mk. 5, ich werde ihn fliegen.\n\nSobald wir Furorion gerettet haben, sprengen wir uns den Weg zu all den anderen Überlebenden frei!", sourceObjective = "Fliegt im Turboholperer Mk. 5 mit und jagt die Armee der Untoten in die Luft.", completion = "Ich danke Euch, Fremder. Ich habe die Horde enttäuscht... Ich war nicht stark genug, um diese Bedrohung allein aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59943] = { id = 59943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Harpyienproblem", description = "Die Oger wollen den Rest der Expedition für ihr Ritual opfern, mit dem sie die Kontrolle über Kalecgos, den Anführer des blauen Drachenschwarms, erlangen.\n\nEs scheint, dass einer der Überlebenden in die Hügel nördlich von hier gebracht worden ist. Bo ist vorausgegangen, um der Sache nachzugehen.\n\nKommt, wir sehen nach, was er herausgefunden hat.", sourceObjective = "Trefft Euch mit Bo in der Nähe des Harpyiennests.", completion = "Ich habe das verschollene Mitglied der Expedition gefunden... aber wir müssen uns erst um eine Reihe von Problemen kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[59944] = { id = 59944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rettung von Herbert Schattenstoß", description = "Die Harpyien haben vor, einen Verlassenen namens Herbert Schattenstoß, den Magier der Expedition, zu opfern.\n\nHerberts ethische Werte sind... fragwürdig, aber er bemüht sich immer, der Horde zu helfen. Wir werden seine Magie brauchen, um die Oger aufzuhalten.\n\nGehen wir.", sourceObjective = "Rettet Herbert Schattenstoß vor dem nekrotischen Ritual der Harpyien.", completion = "Danke für die Rettung! Sie müssen dringend Opfer brauchen, wenn sie jemanden benutzen wollen, der schon tot ist.\n\nWenn jemand mir meine Lebensessenz für ein verbotenes Ritual entzieht, dann ich selbst!", sourceObjectiveStatus = "unverified-source-field" }
quests[59945] = { id = 59945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpyienausdünnung", description = "Die Harpyien scheinen mit den Ogern unter einer Decke zu stecken. Viele von ihnen versammeln sich, um unser Lager anzugreifen.\n\nWir müssen sie dezimieren und ihre Versuche, uns auszulöschen, vereiteln.\n\nVielleicht lernen sie, dass es das Beste ist, die Horde in Ruhe zu lassen.", sourceObjective = "Besiegt 10 Harpyien und ihre Verbündeten.", completion = "Die Harpyien scheinen sich in ihren Horst zurückzuziehen. Das sollte uns Zeit geben, die Oger aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59946] = { id = 59946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemläuterung", description = "Die Harpyien haben im ganzen Gebiet widerwärtige Totems platziert, um ihre Macht zu steigern.\n\nWir müssen diese Totems zerstören, um unseren Feind zu schwächen.\n\nNehmt diese Fackel und brennt alle Totems nieder, die Ihr seht. Es ist weise, den Gegner zu schwächen, noch bevor die Schlacht beginnt.", sourceObjective = "Zündet 5 Harpyientotems an.", completion = "Die Harpyien werden schwächer, wenn ihre Totems zerstört sind. Hoffentlich erkennen sie, dass man sich nicht mit der Horde anlegen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[59947] = { id = 59947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an die Basis", description = "Wir sollten zum Lager zurückkehren und Herbert mitnehmen.\n\nWir sind einen Schritt weiter, den Ogern und ihren Plänen einen Strich durch die Rechnung zu machen.", sourceObjective = "Kehrt zum Lager der Horde zurück und sprecht mit Thrall.", completion = "Es ist schön, Euch alle unversehrt wiederzusehen. Ihr seid der lebende Beweis für die Willensstärke der Horde!\n\nHoffentlich ist dieser Schattenstoß so mächtig, wie er verwirrt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[59948] = { id = 59948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westwärts", description = "Thrall will, dass wir den Westen auskundschaften und den Schauplatz des nächsten Rituals finden.\n\nWir könnten Eure Hilfe brauchen. Ich bin schon einmal gestorben. Ich würde es vorziehen, diese Erfahrung nicht zu wiederholen.", sourceObjective = "Trefft Lana Jordan westlich des Lagers der Horde.", completion = "Eine riesige Grube voller nekrotischer Energie und Spinnen.\n\nIch habe Spinnen mal gehasst. Jetzt, als Verlassene, kommen sie mir gar nicht mehr so übel vor.\n\nSie würden einen trotzdem sofort töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[59949] = { id = 59949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grobe Grube", description = "Aus dieser Grube strömt eine große Menge Schattenenergie. Ich glaube, dass dort unten ein Ritual ausgeführt wird. Und das bedeutet ein Opfer.\n\nHört Ihr das auch? Seit ich dieses neue Ohr angenäht bekommen habe, höre ich wirklich ausgezeichnet.\n\nEs klingt, als wären dort unten noch mehr unserer Soldaten gefangen. Vermutlich alle eingesponnen.\n\nWon'sa und ich werden... hier oben bleiben und allen helfen, die es herausschaffen.\n\nIhr solltet reinspringen und alle retten, die sich noch da unten befinden!", sourceObjective = "Rettet 5 gefangene Expeditionsmitglieder.", completion = "Crenna Erdentochter ist für unser Vorhaben von entscheidender Bedeutung. Ihre Verbindung mit der Natur wird uns helfen zu verstehen, was diese Oger mit der Insel gemacht haben.\n\nGute Arbeit, Rekrut.", sourceObjectiveStatus = "unverified-source-field" }
quests[59950] = { id = 59950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorräte aufstocken", description = "Versorger Jin'hake konnte ein paar weitere Vorräte aus dem Schiffswrack sichern.\n\nIch möchte, dass Ihr prüft, ob Euch etwas davon nützlich sein kann, bevor wir losziehen, um die Rituale zu beenden.", sourceObjective = "Kauft irgendeinen Gegenstand von Versorger Jin'hake und verkauft einen beliebigen Gegenstand an ihn.", progress = "Versorger Jin'hake sollte ein paar nützliche Vorräte für Euch haben.", completion = "Ich hoffe, Ihr habt, was Ihr braucht.\n\nThrog hat diese Tasche in der Nähe gefunden und dachte, Ihr könnt sie vielleicht brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59951] = { id = 59951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gestalten eines Druiden", description = "Danke, dass Ihr mich gerettet habt, {name}. Erlaubt mir, Euch dafür bei Euren Studien des Druidentums zu helfen.\n\nIch habe die Gestalt eines Hirsches angenommen, um aus dieser Grube zu entkommen. Ich habe eine Idee, wie auch Ihr lernen könnt, das zu tun.\n\nFolgt mir. Ganz in der Nähe steht ein uralter Druidenstein. Lasst uns dort Zwiesprache mit der Natur halten.", sourceObjective = "Haltet Zwiesprache mit dem Druidenstein in der Nähe.", progress = "Kommt. Wir haben keine Zeit zu verlieren.", completion = "Gut! Ich spüre, wie der Segen der Geister Euch durchströmt.\n\nKonzentriert Euch. Dann solltet Ihr merken, dass Ihr eine neue Gestalt annehmen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59952] = { id = 59952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Falle des Jägers", description = "Wer sich einen wahren Jäger nennen will, sollte etwas über das Fallenstellen gelernt haben.\n\nGlücklicherweise bin ich ein echter Experte darin.\n\nZuerst müsst Ihr Vorräte in der Gegend sammeln, um eine ordentliche Eiskältefalle auszustatten.\n\nHerbert hat bestimmt ein Eispartikel. Für den Rest müsst Ihr Euch bloß hier in der Gegend umsehen.\n\nIhr braucht die Falle für ein weiteres Problem, das kürzlich aufgekommen ist.", sourceObjective = "Sammelt Bestandteile in der Gegend, um eine Eiskältefalle zu bauen.", progress = "Habt Ihr alles Nötige besorgt? Herbert sollte das Eispartikel haben und die anderen zwei Sachen findet Ihr in der Nähe.", completion = "Mit etwas Arbeit wird das eine effektive Falle.\n\nEin Teil dessen, was einen richtigen {class} ausmacht, ist der Einfallsreichtum, das nutzen zu können, was die Umgebung hergibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59953] = { id = 59953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf den Pirscher", description = "Nachdem Ihr nun Eure Falle habt, können wir uns dem eigentlichen Problem widmen.\n\nEine seltsame Kreatur, die nicht von dieser Insel stammt, ist bei unserem Lager herumgeschlichen.\n\nIch finde, wir sollten sie gefangen nehmen und herausfinden, ob sie uns helfen kann.\n\nLegt die Eiskältefalle in diesen Ruinen aus, um sie herauszulocken. Dann werden wir ja sehen, womit wir es zu tun haben.", sourceObjective = "Legt Eure Eiskältefalle in den Ogerruinen aus, um das wilde Tier herauszulocken, das um das Lager schleicht.", completion = "Ich muss zugeben, dass es mich beschämt hat, das Tier nicht sofort erkannt zu haben.\n\nEs muss ganz schön robust sein, wenn es so lange allein überlebt hat!\n\nHier, ich will Euch noch einen Trick beibringen. Ihr braucht mehrere Tiere, die Ihr auswechseln könnt, wenn Ihr ein echter {class} werden wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59954] = { id = 59954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Magier", description = "Für <einen Anfängermagier/eine Anfängermagierin> seid Ihr recht versiert. Ein paar Dinge müsst Ihr aber noch lernen.\n\nZum einen scheint Ihr keine Ahnung von 'Verwandlung' zu haben.\n\nAnsonsten hättet Ihr es nämlich auf die Harpyien angewendet, die uns angegriffen haben!\n\nDas sollten wir jetzt ändern. In meinem Zauberbuch ist genau beschrieben, wie man 'Verwandlung' wirkt... Aber die Angreifer haben es in den nahe gelegenen See geworfen.\n\nKönnt Ihr es für mich herausholen? Oh, und nicht vorzeitig einen Blick in das Buch werfen.\n\nDas würdet Ihr auf jeden Fall bereuen.", sourceObjective = "Holt Herbert Schattenstoß' Buch vom Grund des nahe gelegenen Sees zurück.", progress = "Hoffentlich hat mein Buch nicht zu sehr darunter gelitten, am Grunde eines Sees zu liegen.", completion = "Perfekt! Die Seite für 'Verwandlung' ist verschmiert, aber mit etwas Raten kriege ich jeden Zauber raus.\n\nIch werde Euch kurz zeigen, wie man ihn ordnungsgemäß wirkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[59955] = { id = 59955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wozu Schäfchen doch gut sind", description = "Ich kann Euch nicht losziehen lassen, ohne dass Ihr wisst, wie man 'Verwandlung' richtig wirkt.\n\nDenn wenn Ihr den Zauber vermasselt, verwandelt Ihr vielleicht jemanden in etwas völlig anderes!\n\nIch will auf jeden Fall dabei sein und mir Notizen machen, wenn das passiert.\n\nAlso, mal sehen... Ah, Throg wäre perfekt geeignet! Ich erkenne ein gutes Testsubjekt sofort, wenn ich es sehe.\n\nSollen wir anfangen?", sourceObjective = "Übt 'Verwandlung' gegen Herbert und Grunzer Throg.", completion = "Ihr wisst jetzt, wie 'Verwandlung' funktioniert. Ihr solltet den Zauber immer anwenden, wenn Ihr gegen mehr als einen Gegner antretet!", sourceObjectiveStatus = "unverified-source-field" }
quests[59956] = { id = 59956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mönch, ein Fokus", description = "Ihr habt Euch gegen die Harpyien gut geschlagen. Aber wir brauchen noch mehr, um die anstehenden Herausforderungen zu meistern.\n\nWir müssen meditieren und uns konzentrieren, um noch mehr Stärke zu erhalten.\n\nKommt. Ich kenne so einen Ort, der genau richtig für uns ist.", sourceObjective = "Folgt Bo und meditiert mit ihm.", completion = "Ich spüre eine Veränderung in Euch, {name}. Lasst uns mal sehen, was es damit auf sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[59957] = { id = 59957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Sparring", description = "Machen wir noch einen schnellen Sparringskampf, bevor wir ins Lager zurückkehren.\n\nIch spüre die neue Kraft in Euch wachsen. Ich will mir einen praktischen Eindruck davon verschaffen!", sourceObjective = "Kämpft gegen Bo.", completion = "Ihr seht stärker aus! Gut. Wir brauchen solche Stärke, wenn wir diese Oger zerschmettern wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59958] = { id = 59958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dienst eines Paladins", description = "Während Ihr die Untotenarmee erledigt habt, hat der Geist eines Paladins mich angesprochen... und nach Euch gefragt!\n\nEr ist über den Ruinen in der Nähe geschwebt.\n\nIhr solltet herausfinden, was dieser Geist will. Ich weiß nicht viel über das Licht... aber ich weiß, dass man einen Geist nicht ignorieren sollte.", sourceObjective = "Sprecht mit dem Paladingeist.", completion = "Wer dem Licht dient, weiß um seinen Segen. Nehmt nun dieses Geschenk, {class}.\n\nNutzt es, wenn Eure Kräfte schwinden, wenn alle Hoffnung verloren scheint. Das Licht wird Euch vor dem Übel beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59959] = { id = 59959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Brandmal hat den Schlüssel", description = "<Darion ist nicht ansprechbar. Der Käfig ist verschlossen und sieht nicht einfach zu knacken aus.\n\nVielleicht ist der Träger des Schlüssels dieses \"Brandmal\", von dem er sprach.>", sourceObjective = "Findet den Schlüssel, um Darion zu befreien.", progress = "Seid Ihr bereit, Euch meinen Vorschlag anzuhören?", completion = "Meine Güte. Ein Tag voller Überraschungen!\n\nNun, Sterblicher... ich bin neugierig, was Euch zurück in den Schlund geführt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[59960] = { id = 59960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spur wird kalt", description = "<Das Amulett brennt in Eurer Hand. Die Magie, die es durchströmt, zerrt leicht an Eurem Griff.\n\nVielleicht kann die Verzauberung, von der Bolvar sprach, dazu benutzt werden, Mograine zu finden.>", sourceObjective = "Benutzt das Amulett der Reiter, um Darion Mograine zu finden.", completion = "<Darion ist im Käfig gefangen. Er scheint bewusstlos zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[59961] = { id = 59961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Priesters", description = "Ihr seid <ein ausgebildeter Priester/eine ausgebildete Priesterin>, nicht wahr, {name}? Ich habe einen schauerlichen Auftrag für Euch.\n\nIch bin ein paar verwundeten Teilnehmern der ersten Expedition begegnet. Ich habe getan, was ich konnte... aber es war schon zu spät.\n\nKönnt Ihr ein Ritual ausführen, damit sie ihre Ruhe finden?\n\nIhre Geister haben es verdient, ehrenvoll zu ruhen.", sourceObjective = "Findet die Leichen der Rekruten der ersten Expedition.", completion = "Keine Zeit zum Red'n. Diese Rekruten sin' kaum noch am Leb'n!\n\nIch bring Euch bei, wie man 'Auferstehung' wirkt. Nur das kann sie zurückzuhol'n.\n\nIch hoff, dass Ihr damit umgeh'n könnt, denn das is'n echt mächtiger Zauber.", sourceObjectiveStatus = "unverified-source-field" }
quests[59962] = { id = 59962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung stirbt nie", description = "Ihr sucht hier also nach jemandem, <Sterblicher/Sterbliche>. Nun, da ich recht schlau bin, weiß ich eventuell, wo diese Person sich befindet.\n\nErlaubt mir, Euch einen Handel vorzuschlagen. Das Amulett, das Ihr tragt... Es besitzt interessante Kräfte.\n\nIhr gebt mir das Amulett, und ich helfe Euch, diesen Maldraxxibaron zu finden.\n\nUnd dann geht Ihr. Ich möchte nicht unhöflich erscheinen, aber ich möchte keine Aufmerksamkeit erregen.\n\nLasst mich die Dinge etwas beschleunigen.", sourceObjective = "Folgt Ve'nari.", completion = "Haltet Schritt. Wir haben nicht viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[59965] = { id = 59965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auferstehung der Rekruten", description = "Ihr müsst 'Auferstehung' auf die Rekruten wirk'n, um sie zu rett'n.\n\nDie nekrotische Magie von diesem Ort zerrt an ihren Seel'n.\n\nSchnell jetzt!", sourceObjective = "Wendet 'Auferstehung' auf 3 Rekruten der ersten Expedition an.", progress = "Na los. Benutzt 'Auferstehung', um den Rekruten zu helfen.", completion = "Ihr habt das volle Mojo zu 'nem groß'n {class}.\n\nMeine Aufgabe is' erledigt. Zeit für mich, die andre Seite zu seh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[59966] = { id = 59966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer hinein", description = "Es ist sehr spannend, einen sterblichen Geschäftspartner zu haben! Dieses Amulett ist faszinierend.\n\nBitte was? Ach ja, der Baron, nach dem Ihr sucht...\n\nIch habe zufällig von einem Maldraxxikriegsfürsten gehört, der im unteren Hof der Verdammnisfestung festgehalten wird. Wie Ihr dem Namen entnehmen könnt, ist es kein besonders einladender Ort.\n\nIch rate Euch, der Aufmerksamkeit der Vasallen des Kerkermeisters zu entgehen. Ich habe da genau das Richtige.\n\nAuf Euer Zeichen verberge ich uns vor den Schlundgebundenen.", sourceObjective = "Folgt Ve'nari zur Verdammnisfestung.", completion = "Mein Vater... Alexandros Mograine. Der Aschenbringer.\n\nIch hätte nie gedacht, dass ich ihn wiedersehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[59967] = { id = 59967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Schurken", description = "Shuja hat eine Schurkin von der ersten Expedition erwähnt. Ihr Name ist Drizza Seitenstich.\n\nDrizza wurde zuletzt unterwegs nach Nordwesten gesehen... in Richtung einer großen Bärenhöhle.\n\nNiemand von uns kann sich so gut anschleichen wie Ihr. Versucht, Drizza zu finden und sie hierher zurückzubringen.", sourceObjective = "Schleicht Euch mit 'Verstohlenheit' unbemerkt durch das Gelände und sucht den Schurken der ersten Expedition.", progress = "Habt Ihr die Wurzeln? Stellt sicher, dass dieser Bär weit weg ist, wenn Ihr sie erntet.", completion = "Hier ist das Geheimnis, wie man diese Gifte herstellt. Hat mich einige Zeit gekostet, das herauszufinden.\n\nAber da Ihr jetzt wisst, wie man sie herstellt, könnt Ihr diesen Oger für mich töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[59968] = { id = 59968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tödlichste aller Gifte", description = "Ihr habt das Gift. Jetzt müsst Ihr den Oger ausschalten. Das Monstrum heißt Gutgruk der Zähe.\n\nNormalerweise patrouilliert er um die Zitadelle. Ich wette, er sucht genau in diesem Augenblick nach Eurer Expedition!\n\nVergiftet Eure Klingen und erledigt das Monster. Zeigt ihm, dass er gar nicht so zäh ist!", sourceObjective = "Tötet Gutgruk den Zähen.", completion = "Drizza Seitenstich ist ehrenhaft gestorben. Man wird sich als Heldin der Horde an sie erinnern.\n\nUnd jetzt wisst Ihr, wie man Gift herstellt. Haltet es... einfach weg von mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[59970] = { id = 59970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Handel eines Hexenmeisters", description = "Als ich die Gegend ausgespäht habe, habe ich ein offenes Portal nahe der Brücke auf dem Hügel gesehen. Das bedeutet nichts Gutes für uns.\n\nEs scheint, als ob ein anderer Hexenmeister vergeblich versucht hätte, das Portal zu schließen.\n\nIch weiß, dass Ihr mit solchen... Dingen zu tun habt. Vielleicht könnt Ihr Euer Wissen einem guten Zweck zuführen und das Portal schließen.", sourceObjective = "Untersucht die Leiche des Hexenmeisters der ersten Expedition.", progress = "Ich sehe, Ihr habt das Grimoire, das für das Bindungsritual verantwortlich ist.", completion = "Unsere Abmachung gilt.\n\nRuft mich aus der Leere, und ich eile herbei.\n\n<Der Leerwandler sieht zur Leiche des Goblins.>\n\nDann wollen wir mal sehen, ob Ihr stärker seid als die, die vor Euch kamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59971] = { id = 59971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Kriegers", description = "Seid gegrüßt, {name}! Ihr seid stärker geworden, seit wir auf dem Boot gekämpft haben. Eines Tages werdet Ihr vielleicht <ein bekannter Krieger/eine bekannte Kriegerin> sein!\n\nDa fällt mir ein...\n\nIch bin auf der Brücke im Norden einem seltsamen Geist begegnet, der verlangt, einen echten Krieger zu treffen.\n\nVielleicht könnt Ihr ja mal schauen, was er will.\n\nEr scheint nicht feindlich gesinnt zu sein. Vielleicht will er uns ja sogar helfen.", sourceObjective = "Sprecht mit dem seltsamen Geist an der Finsterbrecherbrücke.", completion = "Ihr seid nicht der Held aus Mythen und Legenden... Aber Ihr habt Potenzial.\n\nSteht still und ich teile meine mächtigste Technik mit Euch.\n\nUnd dann bitte ich Euch, mich endlich von diesem Leid zu erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59972] = { id = 59972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hjalmars endgültige Hinrichtung", description = "Jetzt beherrscht Ihr meine stärkste Fertigkeit, <junger Krieger/junge Kriegerin>.\n\nVersetzt mir nun damit den endgültigen Todesstoß! Seit einer halben Ewigkeit halten diese Oger meinen Geist hier gefangen, weil ich es gewagt habe, mich gegen sie zu stellen.\n\nNur ein glorreicher Tod kann mir die ewige Ruhe schenken.\n\nUnd nur dann werde ich im nächsten Leben meine Brüder und Schwestern wiedersehen.", sourceObjective = "Tötet Hjalmar den Unvergänglichen. Um ihn wirklich zu töten, müsst Ihr 'Hinrichten' einsetzen.", completion = "Ihr scheint stärker zu sein! Wenn doch nur alle Geister so ehrenhaft wie dieser wären...", sourceObjectiveStatus = "unverified-source-field" }
quests[59973] = { id = 59973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bindung stärker als der Tod", description = "Seit ich die Schattenlande betreten habe, war ich so auf unsere Mission konzentriert, dass ich nie daran gedacht hätte, dass die Seelen meiner Familie hier sein könnten.\n\nWas auch immer dieses Reich Maldraxxus sein mag, ich hoffe, dass es der Dienste meines Vaters würdig ist!\n\nWir müssen ihn befreien, {name}. Ich habe... Ich habe ihm viel zu sagen.", sourceObjective = "Beschützt Darion, während er Alexandros befreit.", progress = "Jeder Augenblick, den man hier verbringt, zerrt einem an der Seele.", completion = "Ich kann Euch nicht genug danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59974] = { id = 59974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gerettete Seele", description = "Vyraz... die ganze Zeit...\n\nDas ist nicht hinnehmbar, {name}. Wir müssen Krexus rächen und ihn auslöschen!\n\nAls er Euch in den Schlund schickte, ging er davon aus, dass Ihr nie wieder zurückkehren würdet. Er hat Euch unterschätzt. Ein tödlicher Fehler.\n\nGeht mit Mograine und holt Euch Vyraz' Kopf. Ich werde unsere Truppen beim Sitz des Primus warnen.", sourceObjective = "Trefft Alexandros Mograine im Haus der Auserwählten in Maldraxxus.", completion = "Ich kann diese Wunde nicht länger schwären lassen. Ich werde sie hier und jetzt ausbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59975] = { id = 59975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Finsterbrecherzitadelle", description = "Der letzte Überlebende ist in der Ogerzitadelle gefangen.\n\nCrenna und Herbert haben einen Plan, wie sie uns da reinbringen.\n\nEine kleine Gruppe von uns trifft sich im Norden. Ihr kommt mit uns.\n\nWenn wir hier scheitern, werden die Oger die Kontrolle über Kalecgos und die mächtige Magie des blauen Drachenschwarms erlangen.", sourceObjective = "Trefft Thrall außerhalb der Finsterbrecherzitadelle.", completion = "Da vorne ist die Finsterbrecherzitadelle.\n\nHerberts vorgeschlagener Plan ist etwas... unkonventionell.", sourceObjectiveStatus = "unverified-source-field" }
quests[59978] = { id = 59978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau vor ihren Nasen", description = "Wir müssen in die Finsterbrecherzitadelle, den letzten Überlebenden retten und Gor'groth beseitigen.\n\nHerbert und Crenna werden einen Zauber wirken, damit Ihr wie ein Oger ausseht... Und dann bringt Ihr uns als \"Gefangene\" rein.\n\nSprecht mit Herbert, wenn Ihr bereit seid.", sourceObjective = "Lasst Euch von Herbert Schattenstoß in einen Oger verwandeln und späht die Ogerzitadelle in der Nähe aus.", completion = "Es gibt vielleicht eine Möglichkeit, wie wir Kriegsherr Donnerfuß retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[59979] = { id = 59979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Oger zur Schlachtbank", description = "Das ist alles schlimmer, als ich dachte. Die Oger waren darauf vorbereitet, dass wir einen Rettungsversuch wagen würden.\n\nSie scheinen einen Angriff auf unser Lager zu planen, während sich ihr Ritual dem Ende zuneigt.\n\nDas darf nicht geschehen. Zerschmettert die Oger! Zeigt ihnen die Stärke der Horde!", sourceObjective = "Tötet 8 Oger in der Finsterbrecherzitadelle.", progress = "Gewährt den Ogern keine Gnade!", completion = "Das sollte die Oger lange genug schwächen, damit wir ihre Pläne zunichtemachen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[59980] = { id = 59980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katapultsprengung", description = "Beim Hineinschleichen habe ich gesehen, dass die Oger Katapulte aufstellen, um unser Lager zu zerstören.\n\nCork muss so etwas geahnt haben, denn er hat mir \"nur für den Fall\" einige Sprengsätze gegeben.\n\nNehmt diese Sprengsätze und zerstört die Katapulte!\n\nUnd schüttelt sie nicht zu stark.", sourceObjective = "Jagt 4 Katapulte in der Finsterbrecherzitadelle in die Luft.", completion = "Gute Arbeit! Ihr habt nicht zufällig ein paar Sprengladungen aufgehoben, oder?\n\n...Hatte ich auch nicht erwartet. Aber was soll's. Ich kenne noch jede Menge anderer Wege, meine Feinde zu zerfetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59981] = { id = 59981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle über ihre Steine", description = "Kriegsherr Donnerfuß wird nicht viel länger durchhalten. Bald ist seine Lebensessenz gänzlich aufgezehrt.\n\nGor'groth erwähnte, dass sie ihn mit Wärtersteinen festhalten.\n\nIch möchte, dass Ihr diese Wärtersteine holt und hierher zurückbringt, um Donnerfuß zu befreien.", sourceObjective = "Beschafft die Wärtersteine von Jugnug, Wug und Grunk und benutzt sie, um Kriegsherr Donnerfuß zu befreien.", progress = "Das waren also die Wärtersteine, mit denen ich gebunden wurde? Vielleicht haben sogar die Oger schon von meiner Stärke gehört!", completion = "Danke für Eure Hilfe, aber meine Rettung wird die Oger nicht aufhalten.\n\nSie haben genug Lebensessenz, um das Ritual abzuschließen!", sourceObjectiveStatus = "unverified-source-field" }
quests[59984] = { id = 59984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungeon: Finsterbrecherzitadelle", description = "Gor'groth will Schattenmagie nutzen, um Kalecgos, den Aspekt des blauen Drachenschwarms, zu kontrollieren.\n\nEr hat genug Lebensessenz gesammelt, um das Ritual beenden zu können. Ich weiß nicht, was geschehen wird, aber wir dürfen nicht zulassen, dass er es vollendet!\n\nGor'groth wird erst aufhören, wenn er tot ist!\n\nIhr müsst die Zitadelle stürmen und Gor'groth töten, bevor er sein Ritual vollenden kann!\n\nIch wünschte, ich könnte mit Euch angreifen, aber ich erhole mich noch immer von seiner dunklen Magie.", sourceObjective = "Schließt den Dungeon \"Finsterbrecherzitadelle\" ab.", completion = "Sieg für die Horde! Es ist an der Zeit, dass wir als Helden und Eroberer nach Orgrimmar zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59985] = { id = 59985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende vom Anfang", description = "Ihr habt hier gute Arbeit geleistet, {name}. Kalecgos und Furorion wollen zu den Dracheninseln weiterziehen.\n\nIch muss nach Orgrimmar zurückkehren. Diese Schattenmagie ist beunruhigend... Ich muss sie genauer untersuchen.\n\nSprecht mit Kalecgos. Er wird Euch auf die Dracheninseln bringen und Euch erklären, was dort vor sich geht.", sourceObjective = "Sprecht mit Kalecgos, um zu den Dracheninseln zu reisen.", completion = "Es ist gut, wieder in Orgrimmar zu sein.\n\nIch muss mich beim Kriegshäuptling melden. Aber ich weiß, was Ihr bis dahin tun könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[59986] = { id = 59986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die weite Welt der Katalysatoren", description = "Es gibt verschiedene Formen von Katalysatoren. Vorerst werden wir Euch zwei von ihnen vorstellen.\n\nTempokatalysatoren können den Wiederherstellungsprozess beschleunigen. Das kann uns natürlich dabei helfen, zu regeln, wie viele Seelen wir wiederherstellen können.\n\nQualitätskatalysatoren verbessern die Qualität der materiellen Güter, die ein Geist nach seiner Wiederherstellung zu bieten hat.\n\nKehrt zu mir zurück, wenn ihr von jeder Sorte einen gefunden habt. Ich bin sehr darauf gespannt, ob Eure winzigen Augen scharf genug sind, um sie zu entdecken.", sourceObjective = "Identifiziert die verschiedenen Sorten von Katalysatoren.", sourceObjectiveStatus = "unverified-source-field" }
quests[59994] = { id = 59994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauensfall", description = "Denken wir über die Bedeutung der letzten Worte des Archivars nach: \"Der Sieg gehört nur jenen, die den Fall nicht fürchten.\"\n\nHmm. Es könnte sich auf die Schrift des Sieges beziehen. Das ist die bekannteste aller Schriften, von denen gesagt wird, dass sie in diesem Turm aufbewahrt werden.\n\nDas Buch ist unbezahlbar, {name}. Ich meine das fast wörtlich. Wir müssen alles tun, was nötig ist, um es zu finden!\n\nAber, äh... Was glaubt Ihr ist mit \"mutig genug, um zu scheitern\" gemeint?", sourceObjective = "Springt vom Turm.", progress = "Habt Ihr's?", completion = "Das ist sie... die Schrift des Sieges! Die wichtigste Übersicht der Militärgeschichte von Maldraxxus, die je zusammengestellt wurde.\n\nIch muss sie haben! Ähm, wir. Ich meine, wir müssen sie haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[59999] = { id = 59999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergeburt des Hains", description = "Obwohl noch nicht verdorrt, welkt das Konservatorium inmitten der Dürre dahin. Dieser Hain ist nicht mehr das, was er einmal war.\n\nAls Wächter trage ich die doppelte Last von Schuld und Scham. Das Schicksal sorgte für den Verfall dieses Hains und für mein Versagen, das zu verhindern.\n\nAber das Schicksal hat auch die Hoffnung auf seine Erneuerung geweckt. Ihr steht für diese Hoffnung.\n\nIch flehe Euch an, <Sterblicher/Sterbliche>, sucht Zayhad im Herz des Waldes auf und stellt das Verlorene wieder her.\n\nDenn so wie die verwundeten Geister wiedergeboren werden müssen, so muss auch dieser Hain wiedergeboren werden.", sourceObjective = "Wertet das Konservatorium der Königin auf Stufe 2 auf.", completion = "Der Wald singt vor Dankbarkeit, Schlundgänger.\n\nMeine Königin tut gut daran, Euch zu vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60003] = { id = 60003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tapfere Leistung", description = "Es ist einige Zeit her, dass wir es mit so einer großen Zahl der Diener der Geißel zu tun hatten. Auf einen Angriff dieser Größenordnung waren wir schlecht vorbereitet.\n\nObwohl wir viele in Sicherheit bringen konnten, wurden einige in diesem Chaos verwundet.\n\nSucht das Übungsgelände nach Überlebenden des Angriffs ab.\n\nWir brauchen alle Hilfe, die wir bekommen können.", sourceObjective = "Rettet 6 verwundete Recken vom Übungsgelände.", completion = "Wir werden dafür sorgen, dass sich gut um sie gekümmert wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[60004] = { id = 60004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tapfere Leistung", description = "Es ist einige Zeit her, dass wir es mit so einer großen Zahl der Diener der Geißel zu tun hatten. Auf einen Angriff dieser Größenordnung waren wir schlecht vorbereitet.\n\nObwohl wir viele in Sicherheit bringen konnten, wurden einige in diesem Chaos verwundet.\n\nSucht das Übungsgelände nach Überlebenden des Angriffs ab.\n\nWir brauchen alle Hilfe, die wir bekommen können.", sourceObjective = "Rettet 6 verwundete Recken vom Übungsgelände.", completion = "Wir werden dafür sorgen, dass sich gut um sie gekümmert wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[60005] = { id = 60005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr im Verzug", description = "Der Tempel des Mutes darf nicht fallen!\n\nAlle Kyrianer lernen in seinen heiligen Hallen das Kämpfen. Nicht nur, um die Bastion zu beschützen, sondern auch, um ihre eigene Sicherheit zu garantieren, wenn sie Seelen durch den Schleier holen.\n\nReist umgehend dorthin. Sucht Thanikos auf, die treue Hand des Paragons des Mutes.", sourceObjective = "Sucht Thanikos in Xandrias Wacht auf.", completion = "Das ist nicht ganz die Armee, die ich mir erhofft hatte, aber Eure Klinge ist an meiner Seite willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60006] = { id = 60006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt oder nie", description = "In einem fairen Kampf könnten unsere Krieger gegen zahllose Schwärme dieser Maldraxxi bestehen.\n\nDies war kein fairer Kampf, Fremdling.\n\nSie kamen ohne Vorwarnung. Ohne Grund. Wir wurden unvorbereitet getroffen.\n\nSie dürfen nicht noch weiter vordringen. Das muss hier aufhören.", sourceObjective = "Erobert Xandrias Wacht zurück.", completion = "Wir haben einen Schauplatz erworben, aber es gibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[60007] = { id = 60007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrottverwertung", description = "Ich kann die Kernsysteme dieses Kolosses wiederherstellen, aber einige Dinge sind irreparabel. Zum Glück gab es hier genug Zenturionen. Ich glaube, dass wir improvisieren können.\n\nIch brauche Ersatzteile!\n\nIch benötige einen Animakonflux, um seine Systeme aufzuladen, eine Ewigkeitspanzerung, um den Kern zu schützen, und einen archonischen Resonator, damit es wieder rumst!\n\nIch kümmere mich um den Rest. Schnell, schnell!", sourceObjective = "Bergt den Animakonflux, die Ewigkeitspanzerung und den archonischen Resonator.", progress = "Habt Ihr die Teile?", completion = "Das ging schnell! Gut gemacht, wirklich sehr gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[60008] = { id = 60008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerreißen und zerfetzen", description = "Wir werden den maldraxxischen Aufrührern den Preis für ihren Verrat zeigen.\n\nDie nördlichen Gebiete wurden vom Haus der Konstrukte übernommen, der Heimat der unverwüstlichsten Krieger aus Maldraxxus.\n\nDie Aufrührer haben sich heute keine Gnade verdient und wir werden ihnen keine gewähren. Wir werden sie Seite an Seite niedermetzeln, bis dieser heilige Boden gesäubert ist.", sourceObjective = "Tötet Truppen vom Haus der Konstrukte.", progress = "Das ist, was getan werden muss.", completion = "Ihr kämpft mit der Sicherheit eines wahren Kyrianers, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[60009] = { id = 60009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren", description = "Einige unserer Brüder da drin leben noch!\n\nObwohl viele bei dem ersten Angriff ihr Leben verloren haben, scheinen sie die Überlebenden gefangen nehmen zu wollen. Ich weiß nicht, was sie vorhaben, aber ihr Können im Umgang mit Leichen lässt mich das Schlimmste ahnen.\n\nEinige wurden bereits in die Nekropole dort oben gebracht. Andere befinden sich immer noch in Käfigen am Boden. Befreit, so viele Ihr könnt.", sourceObjective = "Rettet 6 gefangene Kyrianer.", completion = "Ihr seid ein treuer Verbündeter. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60013] = { id = 60013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlasst das Mnemis", description = "Ich habe die Dringlichkeit in all Euren Stimmen vernommen, dass Ihr uns verlassen möchtet.\n\nIch werde Eure Abreise beschleunigen. Es gibt eine Transportplattform in der Vorkammer. Ich werde dafür sorgen, dass die Kammer nach Eurer Abreise wieder versiegelt wird.\n\nBitte folgt mir.", sourceObjective = "Benutzt die Transportplattform in der Kammer der Archon.", completion = "Wir müssen uns beeilen. Die Archon muss erfahren, was hier geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[60014] = { id = 60014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande 60 E" }
