quests[60019] = { id = 60019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande 60 E" }
quests[60020] = { id = 60020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein opportunistischer Schlag", description = "Ich bin beeindruckt, dass Ihr es so weit geschafft habt. Aber bildet Euch nicht so viel darauf ein.\n\nDas meiste Kanonenfutter, das Ihr besiegt habt, bestand bestenfalls aus Amateuren. Nur ein einziger Kämpfer wird diese Arena als Champion verlassen.\n\nJedes der fünf... äh, drei Häuser hat Kämpfer aufgestellt. Die meisten wollen nur ihre Grenzen austesten oder etwas Gunst gewinnen. Nur wenige haben eine echte Chance auf den Sieg.\n\nStellt Euch diesen Herausforderern, wenn Ihr heute wahren Ruhm ernten wollt.", sourceObjective = "Tötet 10 Elitestreiter.", completion = "Ihr könnt noch immer stehen? Meine Hoffnungen für Euch steigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60021] = { id = 60021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Champion", description = "Jetzt zeigt Ihr langsam Potenzial! Euer Name muss weithin bekannt in der sterblichen Welt gewesen sein, aus der Ihr stammt.\n\nAber ruht Euch nicht auf Euren Lorbeeren aus. Je härter Ihr kämpft, desto mehr werden sich die anderen mühen, Euch zu besiegen. Das ist der Weg der Maldraxxi!\n\nNichts überzeugt das Publikum mehr, als einen einstigen Champion zu besiegen. Heute nehmen zwei davon teil und versuchen, an einstige Ruhmestaten anzuknüpfen.\n\nStreckt sie nieder!", sourceObjective = "Tötet Champion Rin'mar und Champion Milzriss.", completion = "Gut, das Publikum ist auf Eurer Seite.\n\nNur noch eine letzte Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[60023] = { id = 60023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande (60) E" }
