quests[60040] = { id = 60040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlande (60) E" }
quests[60041] = { id = 60041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monstrositäten leicht gemacht", description = "Wir müssen uns an die Arbeit machen. Jede Seele hier braucht einen Körper.\n\nWir haben die Teile, um einen Körper für Chordy zu bauen. Chordy ist ein großartiger Plünderer, und ihn wiederaufzubauen könnte es uns erleichtern, weitere Konstruktteile zu finden.\n\nWürdet Ihr mir helfen, ihn neu zu bauen?", sourceObjective = "Helft Rathan, einen neuen Konstruktkörper für Chordy zu erschaffen.", completion = "Wir waren erfolgreich, Chordy ist wieder ganz!", sourceObjectiveStatus = "unverified-source-field" }
quests[60042] = { id = 60042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was darf's denn sein?", description = "Chordy ist nur der erste Erfolg, dem viele folgen werden!\n\nWenn neue befreite Seelen hier auftauchen, sprecht Ihr mit ihnen und nehmt ihre Wünsche für neue Konstruktkörper entgegen. Bald werden wir viele neue Konstrukte erschaffen!", sourceObjective = "Nehmt die Anfragen von den anwesenden Seelen entgegen.", completion = "So viele mächtige Seelen! Wir müssen uns sofort an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60043] = { id = 60043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit von oben", description = "Unsere Truppen können nicht vollständig auf dieses Gebiet niederstoßen, solange die Kristalle der Markgräfin den Himmel mit vernichtenden Angriffsschlägen eindecken.\n\nDie schändlichen Schlächter der Markgräfin arbeiten sogar in diesem Moment daran, die verbleibende Anima aus den Kyrianern, die sie bei ihrem Angriff auf die Bastion entführt haben, zu extrahieren. Wir müssen sofort angreifen.\n\nIch werde Euch mit den Flammen des Mutes verzaubern, damit Ihr die Kristalle markieren könnt. Sobald sie markiert sind, werde ich sie aus der Ferne zerstören.", sourceObjective = "Zerstört 5 Maldrazitkerne.", completion = "Ihr habt hier große Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[60044] = { id = 60044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klinge aufladen", description = "Wir können nicht vorrücken, solange die Kolosse unsere Position bombardieren! Ich habe den angegriffen, der uns am nächsten war, aber konventionelle Waffen können ihren verzauberten Häuten nichts anhaben.\n\nGlücklicherweise habe ich aber eine Idee.\n\nSo wie es momentan aussieht, kann Eure Runenklinge ihnen nichts anhaben, aber wenn Ihr Gharmals verstärkte Truppen auslöschen und ihre Essenz auf Eure Klinge übertragen könntet...", sourceObjective = "Ladet Eure Runenklinge auf, indem Ihr feindliche Konstrukte im Flickenhof tötet.", completion = "Vielleicht funktioniert es nicht... vielleicht ist es aber auch unsere letzte Chance auf den Sieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[60048] = { id = 60048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Flicken", description = "Mit den richtigen Ressourcen können wir eine Armee von Konstruktkriegern bauen, wie die Schattenlande sie noch nie gesehen haben.\n\nBesucht Arkadia Moa und seht zu, dass Ihr die benötigten Ressourcen bekommt.", sourceObjective = "Wertet die Monstrositätenfabrik auf Stufe 1 auf", completion = "Ihr habt all die Ressourcen erhalten, die wir benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60049] = { id = 60049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Euren Diensten", description = "Ich glaube, ich sollte Euch ein Lob aussprechen. Ihr habt meine Erwartungen wirklich übertroffen.\n\nRathan kann etwas sentimental sein, aber er hat recht. Dieser Ort kann unser neues Zuhause werden. Hier können wir neue Körper für die von Euch befreiten Seelen konstruieren.\n\nInformiert Baronin Draka, dass sie die Treue von Prinzessin Emeni und den Konstrukten des Metzgerblocks gewonnen hat. Wir werden bereit sein, wann immer sie unsere Hilfe benötigt.", sourceObjective = "Meldet Euch bei Baronin Draka im Sitz des Primus.", completion = "Gut gemacht. Emeni und ihre Konstrukte werden mächtige Verbündete sein.\n\nAllerdings werden sie Eure Hilfe brauchen, um ihr volles Potenzial zu entfalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60050] = { id = 60050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Westfront", description = "Der Aschenbringer und Eure Maldraxxigefährten brauchen Verstärkung am Westtor. Sie werden nicht mehr lange durchhalten!\n\nXandria und meine Leute werden unsere Stellung hier verstärken und in Richtung Gharmal vorstoßen. Wir müssen so schnell wie möglich zu Mograine. Ohne beide Flanken gibt es keine Aussicht auf den Sieg.", sourceObjective = "Fliegt mit Kynthia und meldet Euch bei Alexandros am Flickenhof.", completion = "Ich bin froh, dass Kynthia Euch so schnell gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[60051] = { id = 60051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Meister seines Fachs", description = "Wenn wir ein Reisenetzwerk in Betrieb nehmen wollen, müssen wir einen Meisterspiegelmacher hinzuziehen.\n\nIch habe Gerüchte gehört, dass ein solcher Händler im Glutdistrikt angekommen sein soll. Es wird sicherlich keine großen Überredungskünste benötigen, damit er sich uns anschließt.\n\nKehrt zum Glutdistrikt zurück und findet den Meisterspiegelmacher.", sourceObjective = "Findet Laurent im Glutdistrikt.", completion = "Entschuldigt bitte meine Aufmachung. Ich kann Euch versichern, dass ich mich sonst anders zu kleiden pflege.", sourceObjectiveStatus = "unverified-source-field" }
quests[60052] = { id = 60052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelpack", description = "Das Haus der Rituale besetzt die südliche Hälfte des Tempels. Anders als die Konstrukte vertrauen sie im Kampf hauptsächlich auf ihre endlose Armee aus wiederauferstandenen Kämpfern.\n\nZum Glück wird der archonische Resonator, den wir geborgen, haben, sie erledigen.\n\nWährend wir uns einen Weg durch ihre Streitkräfte bahnen, haltet Ihr mit dem Resonator auf ihre Leichen. Seine Energie wird ihre Seelen zerreißen und sie davon abhalten, wiederaufzuerstehen, um erneut zu kämpfen.", sourceObjective = "Benutzt den archonischen Resonator, um 12 Soldatenleichen des Hauses der Rituale zu zerreißen.", completion = "Der Resonator läuft auf Hochtouren und unsere Gegner sind erledigt. Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[60053] = { id = 60053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Diesem Animakonflux wurde sämtliche Anima entzogen! So ist er einfach nur ein schwerer Metallklotz!\n\nDas ist selbstverständlich nicht Euer Fehler. Ganz und gar nicht. Aber wir müssen ihn aufladen!\n\nDie Maldraxxi haben Extraktoren. Große grüne Kristalle, kann man nicht übersehen. Sie benutzen sie, um gefallenen Kyrianern Anima zu entziehen. Ganz übel!\n\nWir können sie dazu verwenden, den Konflux aufzuladen. Dann wird unser Koloss hier wieder funktionsfähig!", sourceObjective = "Entzieht nekrotischen Extraktoren Anima, um den Animakonflux aufzuladen.", completion = "Noch nicht voll aufgeladen, aber fast! Vielleicht muss ich ein paar Sicherheitsvorkehrungen ausschalten...", sourceObjectiveStatus = "unverified-source-field" }
quests[60054] = { id = 60054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Countdown", description = "Wenn die Brut des Nekromanten in voller Stärke über uns herfällt, bevor der Koloss aufgeladen ist, werden wir untergehen. Das steht außer Frage.\n\nWir müssen seine Aufmerksamkeit so lange fesseln, bis Mikanikos' Arbeit beendet ist.\n\nEr glaubt, dass er den Sieg bereits errungen hat und dass wir nur Schachfiguren sind, mit denen er spielen kann. Wir können seine Überheblichkeit zu unserem Vorteil nutzen und uns wertvolle Zeit verschaffen.\n\nMöge sie ausreichen.", sourceObjective = "Haltet Amarth den Ernter so lange auf, bis der Koloss vollständig aufgeladen ist.", completion = "Wir können jetzt nur vorangehen, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[60055] = { id = 60055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit des Mutes", description = "Ich weiß nicht, was uns jenseits der Schlucht erwartet, Fremdling. Ich hoffe bei der Gnade der Archon, dass mein Paragon noch lebt, aber ich fürchte das Schlimmste.\n\nWir werden uns diesem großen Unbekannten gemeinsam stellen, so wie wir es beim Rest der Schrecken von Maldraxxus getan haben. Kyrianer zu sein, heißt, dem Pfad zu folgen, ganz gleich wie verzweifelt die Umstände sind.\n\nWas immer geschieht, Ihr sollt wissen, dass Ihr Euch heute meinen uneingeschränkten Respekt verdient habt.", sourceObjective = "Stellt Euch gemeinsam mit Thanikos Amarth dem Ernter entgegen.", completion = "Thanikos... ist fort... nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[60056] = { id = 60056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Pfad folgen", description = "Maldraxxus muss sich für seine Verbrechen gegen die Bastion verantworten. Es wird Gerechtigkeit geben!\n\nLasst uns nach Oribos gehen und mit der Geehrten Stimme Tal-Inara sprechen. Wir werden ihr erzählen, was heute geschehen ist. Wir werden ihr sagen, dass die Kyrianer dieser Aggression nicht tatenlos zusehen werden.\n\nArtemede wird die Archon informieren. Meine Brüder und Schwestern werden sich gewiss für den Krieg bereitmachen.\n\nDas darf nicht geschehen.", sourceObjective = "Informiert Tal-Inara in Oribos über den maldraxxischen Angriff auf die Bastion.", completion = "Ich weiß, warum Ihr hier seid. Diese Kyrianerin hat einiges erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60057] = { id = 60057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrotische Schneise: Paragon in Bedrängnis", description = "Xandria, das mächtige Paragon des Mutes, ist die mächtigste Kriegerin unter allen Aufgestiegenen. Doch selbst sie könnte von den stärksten Streitkräften aus Maldraxxus überwältigt werden.\n\nEuer Schicksal ist jetzt mit ihrem verbunden. Ihr müsst Eure Verbündeten sammeln und Euch in die Nekrotische Schneise stürzen, um dafür zu sorgen, dass Amarth und Nalthor es nicht zurück in die Sicherheit ihres Reiches schaffen.\n\nMöge die Archon Eure Klinge direkt in ihre Herzen führen.", sourceObjective = "Besiegt Amarth den Ernter und Nalthor den Eisbinder in der Nekrotischen Schneise.", completion = "Die Kunde Eurer Taten im Tempel des Mutes hat sich in der ganzen Bastion verbreitet, {name}. Xandria hat mich in einer Botschaft wissen lassen, dass Ihr für Euer Heldentum großzügig belohnt werden sollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60058] = { id = 60058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[60060] = { id = 60060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Stolzsturzweiler", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und Stolzsturzweiler zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel in Stolzsturzweiler.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60061] = { id = 60061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zäh wie Seide", description = "Wir sind das Herz der Seidenproduktion im Ardenwald, aber wir können unsere Arbeit nicht tun!\n\nUnser Hain wurde vollständig von Spriggans und diesen merkwürdigen, gestaltwandelnden... Dingern übernommen.\n\nDie Seidenschreiter, die die Seide spinnen, sind höchst empfindliche Kreaturen. Sie brauchen Ruhe und Frieden und ein wenig Musik, um bei Laune zu bleiben! Aber bei all diesen Monstern überall sind sie vollkommen gestresst.\n\nKönnt Ihr bitte dort hineingehen und diese Randalierer beseitigen, damit wir wieder loslegen können?", sourceObjective = "Tötet in den Gespinstklippen Angreifer, rettet Pfleger und lasst Seidenschreiterlarven schlüpfen.", completion = "Danke! Wir sind Euch so dankbar für Eure Hilfe bei der Beseitigung dieser Schufte und der Rettung unserer Leute.", sourceObjectiveStatus = "unverified-source-field" }
quests[60062] = { id = 60062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zerschmetterte Harfe", description = "<Die Harfe liegt zerbrochen da und einige Teile fehlen.\n\nVielleicht könnt Ihr noch weitere Teile finden und jemanden darum bitten, sie zu reparieren.>", sourceObjective = "Findet Teile der zerbrochenen Harfe.", progress = "Ich habe meine Harfe verloren! Sie wurde von diesen grässlichen Kreaturen gestohlen und zerstört.", completion = "Ihr habt meine Harfe gefunden! Und die fehlenden Teile. Nur einen Moment, dann kann ich sie reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60063] = { id = 60063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Lied für die Seidenschreiter", description = "Na also, die Harfe ist repariert. Wenn ich nicht so schwer verwundet wäre, würde ich sie zu den Seidenschreitern bringen, aber Ihr seid stark. Ihr könnt ihnen helfen.\n\nUnsere wertvollen Seidenschreiter sind überall in den Klippen. Wenn Ihr einen findet, spielt die Harfe, dann geben sie Euch frische Seide. Sorgt aber vorher dafür, dass niemand in der Nähe ist, der ihnen Stress verursachen könnte!\n\nWenn Ihr Euch dringend schnell fortbewegen müsst, nehmt einfach einen der Seidenverschießer da neben mir. Zielt auf die Stelle, an die Ihr wollt, und er wird Seide verschießen, die Euch dorthinzieht!", sourceObjective = "Sammelt Seide von Seidenschreitern, indem Ihr die Harfe für sie spielt.", progress = "Konntet Ihr dabei helfen, die armen Seidenschreiter zu beruhigen und ihre Seide zu bekommen?", completion = "Großartige Arbeit! Ich bin sicher, die Seidenschreiter wussten das von Euch gespielte Lied zu schätzen. Ihr seht aus wie jemand, der die feinen Künste zu schätzen weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[60064] = { id = 60064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alte Gertie retten", description = "Wir müssen die alte Gertie finden! Sie ist die Brutmutter der Seidenschreiter und unsere verlässlichste Produzentin. Wir dürfen sie nicht verlieren.\n\nAber ich kann sie nicht erreichen und nachsehen, ob es ihr gut geht. Normalerweise ist sie oben am höchsten Punkt der Klippen. Könnt Ihr dort hinaufgehen und nachsehen, ob mit ihr alles in Ordnung ist?\n\nFalls nicht... dann möge die Gerechtigkeit den Übeltäter schnell und mit aller Härte einholen.", sourceObjective = "Tötet Noisul mit den vielen Gesichtern.", completion = "<Die alte Gertie ist vor Angst gestorben.\n\nAber diese winzige Seidenschreiterlarve zappelt glücklich bei Eurem Anblick.>", sourceObjectiveStatus = "unverified-source-field" }
quests[60065] = { id = 60065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faden der Hoffnung", description = "<Gertie Jr. sieht hoffnungsvoll zu Euch auf. Vielleicht könnt Ihr sie in Sicherheit bringen.>", sourceObjective = "Bringt Gertie Jr. zu Liliendistel.", completion = "Die alte Gertie ist... tot?\n\nAber Ihr habt ihr Baby gefunden! Danke, ich danke Euch vielmals, dass Ihr es wohlbehalten dort herausgeholt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[60066] = { id = 60066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seide für den Ardenwald", description = "Es ist offensichtlich, dass wir den Ardenwald nicht ständig mit Seide versorgen werden können. Aber es gibt etwas, das helfen wird.\n\nBringt Gertie Jr. und die Seide, die Ihr von den anderen Seidenschreitern gesammelt habt, zurück zum Herz des Waldes. Dort wird sie sicher sein und vielleicht zu so einem majestätischen und schönen Seidenschreiter wie ihre Mutter heranwachsen!", sourceObjective = "Bringt Gertie Jr. zum Herz des Waldes.", completion = "Danke für diese Seide! Aber... ich sehe, Ihr habt noch etwas anderes mitgebracht.\n\nDieser kleine Seidenschreiter ist jetzt in Sicherheit. Ich schwöre es.", sourceObjectiveStatus = "unverified-source-field" }
quests[60067] = { id = 60067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streben nach Gerechtigkeit", description = "Draka ist bereit, die Kräfte der Nekropole auf Gharmal zu entfesseln. Wir müssen ihr nur etwas Zeit verschaffen, damit sie ihre Waffen fokussieren kann.\n\nWas wir jetzt tun, tun wir für uns alle. Die Bastion und Maldraxxus haben vieles an diesen Feind verloren.\n\nGharmal wird nicht leicht zu besiegen sein... aber mit unseren vereinten Kräften werden wir ihn richten!", sourceObjective = "Besiegt Markgraf Gharmal.", completion = "Endlich haben unsere Gefallen Gerechtigkeit erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60068] = { id = 60068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
