quests[60091] = { id = 60091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[60092] = { id = 60092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skoldushalle", description = "<Das Objekt vor Euch ist mit Runen verziert, die in der Sprache der Herrschaft geschrieben sind. Eine dieser Runen reagiert auf Eure Anwesenheit und leuchtet blaugrau auf.>\n\n<Sie lockt Euch, sie zu berühren.>", sourceObjective = "Betretet die Skoldushalle und besiegt ihren Wächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[60096] = { id = 60096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Im Norden rührt sich der Lichkönig.\n\nEine Armee der Untoten marschiert auf seinen Befehl durch Nordend und verbreitet überall auf ihrem Weg die grauenhafte Seuche.\n\nIhr müsst sie aufhalten, {name}.", sourceObjective = "Reist mit einem Schiff nach Nordend.\n\nIhr könnt im Hafen von Sturmwind das Schiff in die Boreanische Tundra oder im Sumpfland das Schiff zum Heulenden Fjord nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60097] = { id = 60097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Auf nach Nordend!", description = "Im Norden rührt sich der Lichkönig.\n\nEine Armee der Untoten marschiert auf seinen Befehl durch Nordend und verbreitet überall auf ihrem Weg die grauenhafte Seuche.\n\nIhr müsst sie aufhalten, {name}.", sourceObjective = "Reist mit dem Zeppelin nach Nordend.\n\nIhr könnt in Tirisfal den Zeppelin zum Heulenden Fjord oder in Orgrimmar den Zeppelin in die Boreanische Tundra nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60098] = { id = 60098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist das Ende", sourceObjective = "Trefft Euch mit Xandria nahe der zentralen Kammer des Hauses der Konstrukte.", completion = "Die Zeit ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60108] = { id = 60108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drust und Verzweiflung", description = "Die Drust dringen in den Hain des Erwachens ein, {name}!\n\nWir müssen zur Verteidigung des Ardenwalds ausschwärmen!", sourceObjective = "Verteidigt den Hain des Erwachens gegen die Drust und tötet Gorak Zhar.", completion = "Gut gemacht, Jäger.\n\nIhr habt den Ardenwald vor den Drust gerettet und damit zahllose andere Reiche vor der Dunkelheit bewahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60110] = { id = 60110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein kleiner Freundschaftsdienst von mir", description = "Mir scheint, Ihr könnt ein wenig Hilfe brauchen, <Schlundgänger/Schlundgängerin>. Ich verfüge über Wissen, das Euch für die Nekrolords nützlicher machen könnte.\n\nAlso werde ich Euch... nur dieses eine Mal... etwas beibringen, und es wird Euch nicht einmal eine Extremität kosten.\n\nGeht das Seelenband mit mir ein, dann sehen wir, ob Ihr etwas lernen könnt.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", completion = "Jetzt könnt Ihr versuchen, meinem Beispiel gerecht zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60111] = { id = 60111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Freundschaft schmieden", description = "Bei Eurer Ankunft war ich mir Eures Potenzials zunächst nicht sicher. Der Primus verlangt solch eine Perfektion in seiner Arbeit... und Ihr seid weit davon entfernt, perfekt zu sein.\n\nJetzt erkenne ich, dass Ihr neues Wissen und neue Ideen in unser Haus bringt. Eure Taten machen uns stärker. Der Primus wäre stolz auf Euch und würde sich wünschen, dass wir alle von Euch lernen.\n\nIch bin jetzt bereit, Eure Gepflogenheiten kennenzulernen.\n\nLasst mich das Seelenband mit Euch eingehen, damit wir gemeinsam stärker werden können.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", completion = "Von unserem geteilten Wissen wird ganz Maldraxxus profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[60112] = { id = 60112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnitt bis auf die Knochen", description = "Ich befürchte, wenn unsere Anwesenheit bemerkt wird, wird auch die Anwesenheit unserer Kameraden bemerkt.\n\nWir müssen unsere Möglichkeiten ausloten. Da die Schmiede in Alarmbereitschaft ist, wird es schwer sein, unentdeckt hindurchzuschleichen.\n\nEs sei denn, Ihr sorgt für eine Ablenkung. Vielleicht reicht es schon, ihre Reihen auszudünnen.", sourceObjective = "Schaltet 5 Osseinarbeiter und 10 brutale Animate aus.", completion = "Er sollte hier sein... ist er aber nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60113] = { id = 60113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dringendes Anliegen", description = "Champion,\n\neine Angelegenheit größter Dringlichkeit erfordert Eure Aufmerksamkeit.\n\nAufgrund der vertraulichen Natur der jüngsten Ereignisse erfahrt Ihr weitere Einzelheiten erst bei unserem Treffen.\n\nWir haben viel zu besprechen. König Graumähne und ich erwarten Eure Ankunft bei der Löwenruh.", sourceObjective = "Meldet Euch bei Genn Graumähne bei der Löwenruh in Sturmwind.", completion = "Ich wusste, Ihr würdet dem Ruf sofort folgen, {name}.\n\nIch werde mich kurz fassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60114] = { id = 60114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftherrschaft", description = "Gharmals Rocs verfügen über die Luftherrschaft und greifen unsere vorrückenden Truppen an. Wir können die Nekropole nicht in Position bringen, bis sie ausgeschaltet sind!\n\nIch würde sie ja selbst töten, aber diese Feiglinge bleiben außerhalb meiner Reichweite und zum Fliegen wurde ich nicht konstruiert.\n\nIhr hingegen seid schlank gebaut. Nehmt meinen Reiterhaken und schwingt Euch auf einen Roc.\n\nWenn Ihr oben seid, schlagt einfach zu, bis er erledigt ist. Kümmert Euch später um die Landung.", sourceObjective = "Holt 6 kampfvernähte Rocs vom Himmel.", completion = "Ich habe ihre Schreie bis hierher gehört. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[60115] = { id = 60115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dringendes Anliegen", description = "Champion,\n\neine Angelegenheit größter Dringlichkeit erfordert Eure Aufmerksamkeit.\n\nAufgrund der vertraulichen Natur der jüngsten Ereignisse erfahrt Ihr weitere Einzelheiten erst bei unserem Treffen.\n\nEs gibt viel zu besprechen. Lordregent Lor'themar Theron erwartet Eure Ankunft in Orgrimmar.", sourceObjective = "Meldet Euch bei Lor'themar Theron in der Feste Grommash in Orgrimmar.", completion = "Es ist einige Zeit her, seit ich zuletzt hier stand und in die Ferne blickte...\n\nWie konnte das passieren?\n\nIch befürchte, ich habe Euch bedrückende Neuigkeiten mitzuteilen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[60116] = { id = 60116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Ablenkung", description = "Das Herz der Allianz wird angegriffen.\n\nDie Geißel der Untoten wimmelt in einer Zahl, wie man sie seit der Rückkehr von Arthas Menethil nicht mehr gesehen hat. Inmitten des Chaos ist etwas... Schreckliches passiert.\n\nWas ich Euch sagen werde, wurde unseren Verbündeten noch nicht mitgeteilt. Sie werden es rechtzeitig erfahren, aber erst muss ich mit Euch sprechen.\n\nErlaubt mir, das zu erklären.", sourceObjective = "Sprecht mit Genn Graumähne bei der Löwenruh in Sturmwind.", completion = "Wir müssen einen Weg finden, Anduin und die anderen zu retten. Aber jetzt ist die Sicherheit unserer Bürger und unserer Verbündeten unsere oberste Priorität.\n\nIch habe mich diesbezüglich an diejenigen gewandt, die im Umgang mit Bedrohungen dieser Art erfahren sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[60117] = { id = 60117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Kreuzzugs", description = "Der unbändige Hunger der Geißel ist entfesselt worden. Es ist nur eine Frage der Zeit, bis diese Monster unsere Straßen überschwemmen.\n\nWir brauchen Fachkenntnisse im Umgang mit dieser Bedrohung. Die Todesritter der Schwarzen Klinge haben sich erboten, uns zu helfen, aber selbst sie können das nicht allein tun.\n\nDer Argentumkreuzzug ist dem Ruf gefolgt. Ihr müsst mit ihnen zusammenarbeiten, um unser Volk zu schützen, {name}.\n\nIch habe ihren Kommandanten von Eurer Ankunft unterrichten lassen. Er erwartet Euch im Lager innerhalb der Stadttore.", sourceObjective = "Sprecht mit Kommandant Gregor im Handelsdistrikt von Sturmwind.", completion = "Ah, ich wurde über die Ankunft eines erfahrenen {class} unterrichtet.\n\nMachen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[60120] = { id = 60120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: In die Scherbenwelt!", description = "Die Brennende Legion – eine riesige Armee aus unzähligen Dämonen – hat die Scherbenwelt, die verwüstete Heimat der Draenei, angegriffen. Es werden Abenteurer der Allianz gesucht, um die Reste der Scherbenwelt vor der vollständigen Auslöschung durch diese Dämoneninvasion zu bewahren.\n\nReist in die Verwüsteten Lande und durchquert das Dunkle Portal.", sourceObjective = "Geht durch das Dunkle Portal in den Verwüsteten Landen.\n\nDer Magier der Ehrenfeste im Magierviertel kann Euch helfen, dort hinzugelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60123] = { id = 60123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Crusade: In die Scherbenwelt!", description = "Die Brennende Legion – eine riesige Armee aus unzähligen Dämonen – hat die Scherbenwelt, die verwüstete Heimat der Orcs, angegriffen. Es werden Abenteurer der Horde gesucht, um die Reste der Scherbenwelt vor der vollständigen Auslöschung durch diese Dämoneninvasion zu bewahren.\n\nReist in die Verwüsteten Lande und durchquert das Dunkle Portal.", sourceObjective = "Begebt Euch durch das Dunkle Portal in die Verwüsteten Lande.\n\nDer Magier von Thrallmar in der Portalkammer von Orgrimmar kann Euch helfen, dorthin zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60125] = { id = 60125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Nach Pandaria!", description = "Bitte kommt unverzüglich zur Burg Sturmwind, um Euch mit König Varian Wrynn zu besprechen.\n\nWir haben von Auseinandersetzungen in den südlichen Gewässern gehört und benötigen Eure Erfahrung als {class} bei der Untersuchung dieser Angelegenheit.", sourceObjective = "Meldet Euch bei Rell Nachtwind in Sturmwind.", completion = "Seid gegrüßt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[60126] = { id = 60126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mists of Pandaria: Nach Pandaria!", description = "Ihr werdet hiermit aufgefordert, Euch unverzüglich in der Feste Grommash zu melden.\n\nWir haben von einem neuen, ressourcenreichen Kontinent im Süden erfahren und beabsichtigen, einen kleinen Trupp Soldaten dorthin zu entsenden, um ihn für die Horde zu beanspruchen.", sourceObjective = "Meldet Euch in der Feste Grommash in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[60127] = { id = 60127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisstes Steinscheusal", description = "Ihr oder ich könnten diese Sündensteine direkt verwenden, aber für solche Aufgaben bevorzuge ich den Einsatz von Steinscheusalen.\n\nHerausragende Resultate, keine persönlichen Risiken.\n\nLeider ist mein Steinscheusal von seinem letzten Einsatz nicht zurückgekehrt.\n\nSprecht mit Grufthüter Kassir oben im Archiv. Er ist ein treuer Anhänger der Anklägerin und wird uns sein Steinscheusal leihen.", sourceObjective = "Sprecht mit Grufthüter Kassir.", completion = "<Grufthüter Kassir grinst.>\n\nIhr habt also endlich auf die Anklägerin gehört, oder?\n\nBesser spät als nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[60128] = { id = 60128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für den Dienst", description = "Keine Sorge wegen Temel. Sein Eifer bezüglich der Sündenverkündung ist mächtig, aber er ist immer noch ein Steinscheusal. Er wird gehorchen.\n\nRichtet Archivar Fane meine Grüße aus.", sourceObjective = "Kehrt zu Archivar Fane zurück.", completion = "Temel hat mir Erstaunliches über Eure gemeinsamen vorherigen Abenteuer erzählt, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[60129] = { id = 60129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einer noch fremderen Welt", description = "<Ihr kommt allein am Rande einer merkwürdigen Stadt an und wisst, dass die Anführer Azeroths immer noch im Schlund gefangen sind.\n\nWo immer Ihr auch seid, es scheint offensichtlich sehr, sehr weit von Eurer Heimat entfernt zu sein.\n\nOffenbar wurde Eure Ankunft bemerkt.>", sourceObjective = "Findet einen Weg in das Innere von Oribos und findet heraus, was dort vor sich geht.", progress = "Versucht, mit den Wachen zu kommunizieren und die Stadt zu betreten.", completion = "Ist es möglich? Ein echter Sterblicher in der Ewigen Stadt? Der Vorsehung sei gedient!", sourceObjectiveStatus = "unverified-source-field" }
quests[60132] = { id = 60132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstellarschriftstücke und Stygia", description = "Es gibt viel im Schlund zu entdecken, und vieles davon lässt sich in zukünftigen Profit ummünzen.\n\nInformationen sind eine Investition.\n\nEs gibt an diesem Ort viele interessante Objekte, und ich handle gerne mit Euch, wenn Ihr welche findet.\n\nFindet eines und wir verhandeln." }
quests[60136] = { id = 60136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Torghast", description = "Das Band mit Eurem Pakt wird stärker, {name}. Gut. Euch wohnt die Macht inne, in Torghast einzudringen und unsere Verbündeten zu retten.\n\nWährend Ihr der Mittlerin im Schlund geholfen habt, konntet Ihr einen Blick auf Baine Bluthuf erhaschen. Vielleicht weiß diese Ve'nari, wie wir in den Turm des Kerkermeisters gelangen und den Häuptling finden können.\n\nBei meinem letzten Blick hinter die Mauern von Torghast wart Ihr an meiner Seite. Ich glaube, diese Verbindung wird es mir erlauben, durch Eure Augen seine Schrecken zu erleben.\n\nSucht Ve'nari auf und erbittet ihre Hilfe, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Findet einen Weg in Torghast hinein, den Turm der Verdammten.", progress = "Tut, was Ihr könnt. Alles hängt von Euch ab.", completion = "Nun, Schlundgänger, worauf wartet Ihr noch?", sourceObjectiveStatus = "unverified-source-field" }
quests[60138] = { id = 60138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore aufschließen" }
quests[60139] = { id = 60139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folterkammer: Jaina", sourceObjective = "Rettet Jaina Prachtmeer aus Torghast.", progress = "Ihr müsst Jaina Prachtmeer in Torghast finden.", completion = "Zwei von Azeroths Architekten des Friedens wurden befreit.\n\nZwei sind noch in Gefangenschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[60145] = { id = 60145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritte Klaue Vartox", description = "Diese Operation, um das Volk für uns zu gewinnen, ist edel und gut.\n\nDennoch müssen wir uns darauf konzentrieren, die Hilfsmittel unseres Feindes zur Strecke zur bringen. Dritte Klaue Vartox, die Anführerin dieses Übergriffs, ist zudem die oberste Steingeborene auf dem Anwesen des Zehntherrn.\n\nWenn wir sie hier und jetzt besiegen, ist der Zehntherr unserem Angriff schutzlos ausgesetzt.", sourceObjective = "Tötet Dritte Klaue Vartox.", completion = "Ausgezeichnet. Jetzt steht er ohne seine wichtigste Verteidigung da.", sourceObjectiveStatus = "unverified-source-field" }
quests[60146] = { id = 60146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folterkammer: Thrall", description = "Ich werde mit dem von Euch geborgenen Totem den abgestimmten Splitter so verändern, dass er Euch zu Thralls Aufenthaltsort führt.\n\n<Bolvar übergibt Euch das kristalline Objekt.>\n\nGebt auf Euch acht. Ihr kennt die Qualen, die Baine und Lady Prachtmeer an diesem verfluchten Ort erlitten haben. Die Gefangenschaft von Thrall wird nicht weniger qualvoll sein.\n\nHütet Euch. Je tiefer Ihr in den Turm der Verdammten vordringt, desto näher kommt Ihr dem Kerkermeister.\n\nBefreit Thrall, {name}... bevor alle Hoffnung verloren ist.", sourceObjective = "Rettet Thrall aus Torghast, Turm der Verdammten.", progress = "Alle unsere Verbündeten müssen gerettet werden, {name}.", completion = "Ihr habt Qualen jenseits der Vorstellungskraft der meisten Sterblichen überstanden, {name}.\n\nWahrlich gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[60147] = { id = 60147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Die Ewige Terrasse", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und der Ewigen Terrasse zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel auf der Ewigen Terrasse.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60148] = { id = 60148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Platz für die Lebenden", description = "<Ein lebender Sterblicher/Eine lebende Sterbliche>... unglaublich!\n\nVergebt mir meine Verwunderung. Ich bin Kah-Delen, eine Aufseherin der Bediensteten der Richterin hier in der Ewigen Stadt Oribos.\n\nIhr befindet Euch hier mitten im Herzen der Schattenlande. Wir sind es zwar gewohnt, Seelen aus allen möglichen Welten der sterblichen Reiche zu erhalten, aber es war noch niemand so... leibhaftig wie Ihr.\n\nAntwortet ehrlich, <Sterblicher/Sterbliche>, seid Ihr tatsächlich dem Schlund entkommen?", sourceObjective = "Die Aufseher möchten mehr darüber erfahren, wie Ihr dem Schlund entkommen seid.", progress = "Wo seid Ihr hergekommen, Fremder?", completion = "Endlich weist uns die Vorsehung wieder den Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[60149] = { id = 60149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Richterin", description = "Ich bin Tal-Inara, die Geehrte Stimme der Richterin. Ich spreche für die, die ewiglich schweigt.\n\nDie Richterin wacht über Oribos. Sie segnet uns mit ihrer Weisheit. Jede sterbliche Seele muss sich ihrem Urteil stellen, nachdem sie die Schattenlande betreten hat.\n\nIm Bruchteil eines Moments sieht sie alles Ruhmreiche, alles Törichte, jede Freude, jedes Bedauern. Mit diesem Wissen wählt sie das beste Nachleben für diese Seele.\n\nZumindest hat sie das bislang getan. Vor nicht allzu langer Zeit hat sich eine Katastrophe ereignet und...\n\nKommt. Einige Dinge lassen sich besser zeigen als erklären.", sourceObjective = "Die Stimme der Richterin wünscht, dass Ihr Euch ihr in der Kammer der Richterin anschließt.", progress = "Die Vorsehung leitet uns immer.", completion = "Vielleicht finden wir in der Vorsehung ein gemeinsames Anliegen. Sie hat Euch zu uns geschickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60150] = { id = 60150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbindung nach Hause", description = "Es ist eine Enttäuschung, dass Ihr die Richterin nicht aufwecken konntet, aber wir dürfen die Hoffnung nicht aufgeben.\n\nEure beständige Anwesenheit in den Schattenlanden könnte unserer Sache dienlich sein. Vielleicht wäre es für Eure Bemühungen nützlich, ein Band mit der Ebene der Sterblichen herzustellen.\n\nDer Kartentisch in dieser Kammer wurde vor lange Zeit von den Ersten eingesetzt, den weisen Architekten all dessen, was Ihr hier seht.\n\nWenn Ihr eine Erinnerung an Eure Heimatwelt habt, dann platziert sie dort. Die Magie des Tisches kann eine Verbindung herstellen.", sourceObjective = "Bringt das Fragment des Helms der Herrschaft an der Konsole an.", completion = "{name}! Ich bin erleichtert, dass Ihr das Reich der Dunkelheit überlebt habt.\n\nIch bin gespannt, was Ihr zu erzählen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60151] = { id = 60151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Passage durch den Schleier", description = "Das Helmfragment hat uns verbunden, während Ihr im Schlund wart. Wie durch eine verdunkelte Glasscheibe habe ich Blicke auf das erhascht, was Ihr erlebt habt. Auf das Grauen, dem Ihr begegnet seid.\n\nZumindest sind die Helden Azeroths noch am Leben. Sie müssen gerettet werden.\n\nDurch das Anbringen des Helms hier habt Ihr eine Verbindung nach Azeroth hergestellt, die ein paar von uns durch den Schleier holen konnte. Aber Ihr und die anderen Helden, die sich uns anschließen, braucht eine stärkere Verbindung.\n\nUnsere Akolythen können Portale dorthin zurück öffnen. Zweifellos werden diese Bediensteten es sehr genau damit nehmen, wo sie platziert werden.", sourceObjective = "Errichtet Portale, die zurück nach Azeroth führen.", progress = "Habt Ihr den Akolythen schon geholfen, die Portale zu öffnen?", completion = "Euer Weg und die Vorsehung sind jetzt miteinander verflochten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60152] = { id = 60152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ewige Stadt", description = "Ihr solltet Euch mit der Ewigen Stadt vertraut machen und wie man sich dort fortbewegt.\n\nWir dienen Oribos als Verwalter.\n\nAlles, was Ihr hier seht, dient der Vorsehung. In diesen Zeiten des Chaos und der Dürre müssen wir unseren Weg anpassen. Es scheint, als sollen wir der Vorsehung auf eine neue Art dienen.\n\nIhr Sterblichen seid nicht die einzigen Besucher hier. Andere kamen vor Euch.\n\nWie Ihr stammen auch die Mittler nicht aus Oribos. Sie sind sehr entgegenkommend und hilfsbereit. Für einen gewissen Preis.", sourceObjective = "Besichtigt die Ewige Stadt Oribos.", progress = "Habt Ihr Eure Besichtigung schon abgeschlossen?", completion = "Wir hoffen, Ihr fühlt Euch hier wohl, {name}.\n\nDiese uralten Einrichtungen stehen Euch zur Verfügung.", sourceObjectiveStatus = "unverified-source-field" }
quests[60153] = { id = 60153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Unbekannte", description = "Kommt Ihr den alten Marasmius besuchen? Ich habe eine ganz besondere Aufgabe für Euch.\n\nEiner meiner Sprösslinge hat einen merkwürdigen Ort gefunden, einen Ort, den ich noch nie zuvor gesehen habe.\n\nIch bin nicht ganz sicher, was sich darin befindet oder ob es gefährlich ist. Aber dafür habe ich ja meine verlässlichen Pilzomanten!\n\nWas sagt Ihr, {name}? Bereit für ein Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", completion = "Wie gut, dass Ihr hier wart. Die Gorm sind in letzter Zeit sehr hungrig und ich schätze es gar nicht, wenn man an mir herumknabbert. Das war noch nie etwas für mich!", sourceObjectiveStatus = "unverified-source-field" }
quests[60154] = { id = 60154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenlande verstehen", description = "All die Jahre, die ich auf dem Frostthron saß, {name}, konnte ich in die Schattenlande blicken. Nur kurze Augenblicke, kaum greifbar. Zugleich wundersam und furchterregend.\n\nWir müssen zusammenarbeiten, um zu verstehen, was passiert ist. Um zu verhindern, dass der Schlund die Realität verschlingt.\n\nWas auch immer Sylvanas und der Kerkermeister wollen, wir müssen sie aufhalten. Aber das können wir nicht allein.\n\nVielleicht kann uns Tal-Inara den Weg zu ein paar Antworten weisen.", sourceObjective = "Sprecht mit Tal-Inara.", progress = "Bringen wir Euren Pfad mit der Vorsehung in Einklang.", completion = "Euer Weg und die Vorsehung werden eins.", sourceObjectiveStatus = "unverified-source-field" }
quests[60155] = { id = 60155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg öffnen" }
quests[60156] = { id = 60156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad zur Bastion", description = "In der Kammer der Richterin liegen Tore zu den endlosen Reichen der Schattenlande. Mit jeder gerichteten Seele öffnete sich ein Tor zu einem angemessenen Leben nach dem Tod. \n\nDoch seit dem... Vorfall blieben alle Tore geschlossen. Sie schlummerten.\n\nWir wagen es nicht, die heilige Kammer der Richterin für so einen profanen Zweck wie Reisen zu benutzen. Aber hier im oberen Ring der Stadt können Tore auf Eure Bedürfnisse angepasst werden.\n\nWir haben die Möglichkeit, ein Tor zu aktivieren. Gemeinsam können wir die Anima kanalisieren, um es mit Energie zu versorgen.", sourceObjective = "Öffnet das Tor zur Bastion.", progress = "Euer Schicksal und die Vorsehung vereinigen sich.", completion = "Die Vorsehung sei gepriesen! Euer Pfad wird deutlicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[60157] = { id = 60157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antworten der Aufgestiegenen" }
quests[60158] = { id = 60158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 7: Verrat ist unausweichlich", description = "Unsere Vereinbarung war recht lukrativ. Verlässliche Mitarbeiter wie Ihr sind nicht leicht zu finden.\n\nIch glaube, dass ich Euch mit einer Aufgabe betrauen kann, die ich normalerweise allein ausführen würde.\n\nBei der Arbeit mit den Ortungsrunen, die Ihr für mich beschafft habt, habe ich in der Nähe ein von einem Mittler hergestelltes Gerät entdeckt. Die gefangen genommene Expedition muss es in den Schlund gebracht haben.\n\nBitte untersucht es und bereitet es für den Rücktransport zur Zuflucht vor. Ich werde bald nachkommen.\n\nDas könnte eine wertvolle Entdeckung sein.", sourceObjective = "Bergt das Mittlergerät außerhalb der Verdammnisfestung.", completion = "Es scheint, dass unsere Partnerschaft ziemlich dauerhaft geworden ist. Das Kartell Ve wird nicht ruhen, bis wir beide ausgeschaltet sind.\n\nIch nehme an, jetzt wäre der Zeitpunkt, Euch über eine meiner wichtigsten Regeln aufzuklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[60159] = { id = 60159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Hallen der Sühne", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und den Hallen der Sühne zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel in den Hallen der Sühne.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60160] = { id = 60160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Der Fluchwald", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und dem Fluchwald zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel im Fluchwald.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60162] = { id = 60162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Zähmung", description = "Es ist eine ziemliche Überraschung, das Tier so gesund und munter zu sehen. Es scheint Euch zu mögen.\n\nWenn Ihr jemals so überragend wie ein Dämmersucher werden möchtet, müsst Ihr lernen, mit verschiedenen Tieren zu arbeiten.\n\nErlaubt mir, es Euch zu zeigen.", sourceObjective = "Lernt von Mithdran Dämmersucher, wie man Tiere fortschickt, zähmt und unterbringt.", progress = "Ihr müsst Euer Tier fortschicken, bevor wir anfangen können. Oh, und wenn es verletzt ist, könnt Ihr es mit 'Tier wiederbeleben' zurückholen.", completion = "Ich glaube nicht, dass ich Euch noch viel beibringen kann, {name}.\n\nJetzt müsst Ihr losziehen und weitere Tiere finden, die Ihr für Eure Zwecke zähmen könnt.\n\nUnd wenn Ihr mal Eure Tiere unterbringen oder zurückholen möchtet, sprecht einfach mich oder andere Stallmeister an, die Ihr auf Euren Reisen trefft.", sourceObjectiveStatus = "unverified-source-field" }
quests[60164] = { id = 60164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Herrschaftsburg", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und der Herrschaftsburg zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel in der Herrschaftsburg.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60165] = { id = 60165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelabstimmung: Fresserdickicht", description = "Die Arbeiten an einem Spiegel wurden abgeschlossen, um das Reisen zwischen Sündensturz und dem Fresserdickicht zu ermöglichen. Allerdings muss er noch abgestimmt werden.\n\nDer Abstimmungsprozess ist relativ simpel. Ihr müsst Euch nur zu dem Spiegel in der Welt begeben, einmal durch ihn durchgehen und dann nach Sündensturz zurückkehren. Wenn Ihr das erledigt habt, werden die Reisen zwischen den Spiegeln eine Leichtigkeit sein.", sourceObjective = "Durchquert den Spiegel im Fresserdickicht.", completion = "Gut gemacht! Die Spiegel sind jetzt abgestimmt und Ihr könnt sie nach Belieben verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60168] = { id = 60168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Zähmung", description = "Schon überraschend, das Tier noch wohlbehalten und am Leben zu sehen. Es scheint Euch zu mögen.\n\nBevor wir die Sache abschließen können, müsst Ihr lernen, mit verschiedenen Tieren zu arbeiten.\n\nIch gebe Euch eine letzte Lektion.", sourceObjective = "Lernt von Austin Haxwart, wie man Tiere fortschickt, zähmt und unterbringt.", completion = "Ausgezeichnete Arbeit, {name}. Ich kann Euch nichts mehr beibringen.\n\nSammelt so viele Wildtiere, wie Ihr mögt. Aber vergesst darüber nicht die Oger, die uns umbringen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60169] = { id = 60169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Gebiets", description = "Der Angriff der Geißel war so plötzlich wie unerwartet. Er hat uns völlig unvorbereitet getroffen.\n\nDurch schnelles Handeln konnten wir unsere Verteidigung bereitmachen... aber nicht, bevor das Turniergelände überrannt war.\n\nWir müssen das Gebiet sichern, bevor wir zum Gegenschlag ansetzen können.\n\nVernichtet diese Monster im Namen des Lichts!", sourceObjective = "Beseitigt 12 Diener der Geißel vom Argentumturnierplatz.", completion = "Es scheint, als ob wir vorankämen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60172] = { id = 60172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diese Quest ist vergänglich", description = "Aus dem Himmel zu fallen ist ein wichtiger Teil dieses Spieltests, also genießt es!", sourceObjective = "Sprecht mit Draedan, um den Schlund zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60174] = { id = 60174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schild des Göttlichen", description = "Diese Insel ist neben der Schattenmagie auch von übler Nekromantie durchdrungen. Das Licht erreicht diesen Ort kaum noch.\n\nNutzt 'Gottesschild', um die Barriere dort unversehrt zu durchqueren und zerstört diesen abscheulichen nekrotischen Altar.\n\nZeigt der Finsternis auf dieser Insel, dass Ihr im Schutze des Lichtes wandelt.", sourceObjective = "Durchquert die nekrotische Barriere mit 'Gottesschild' und zerstört den nekrotischen Altar. Wenn Ihr 'Gottesschild' erneut einsetzen müsst, sprecht mit Daelya Zwielichtbann.", completion = "Das habt Ihr gut gemacht, {name}. Vernichtet diese furchtbare Magie, wo immer Ihr sie vorfindet.\n\nMeine Aufgabe ist erfüllt. Das Licht ruft meinen Namen.\n\nViel Glück und vergesst nie: Wo Ihr auch hingeht, die Wärme des Lichts wird Euch immer beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60175] = { id = 60175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmack von Tirna Noch", description = "Ich bin ein einfacher Pilz mit einfachen Bedürfnissen, {name}. Und was ist einfacher als eine schöne, herzhafte Mahlzeit?\n\nSchaut mich nicht so überrascht an. Ich muss genau wie jedes andere Wesen essen! Wie sonst, glaubt Ihr, hätte ich so groß werden können? Mit schönem, leckerem Kompost!\n\nZu meiner Zeit konnte ich mir aussuchen, wo im Ardenwald ich essen wollte. Jetzt ist das nicht mehr so.\n\nIch habe Appetit auf den Lehmboden, der früher um Tirna Noch herum zu finden war. Ich hatte schon lange keine Sporen mehr da draußen. Könntet Ihr mir etwas davon bringen?", sourceObjective = "Sammelt 6 Lehm mit Blättern in Tirna Noch.", progress = "Tirna Noch ist ein wunderschöner Baum, der östlich des Winterschlafbeckens zu finden ist. Ihr könnt ihn nicht verfehlen.", completion = "Mhmmm, das riecht genauso, wie ich es in Erinnerung habe! Vielleicht ein wenig abgestanden, aber von mir werdet Ihr keine Beschwerden über gut ausgeführte Arbeit hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[60176] = { id = 60176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbringt Euren Zehnt", description = "Leider reicht das Geschenk des Obersten Kämmerers nicht aus, um den gesamten Zehnt zu decken, den wir dem Zehntherrn entrichten sollen, aber es wird ein guter Anfang sein.\n\nDer Verlust der Karawane mit dem Zehnt ist ein herber Schlag für unser Dorf. Unsere kleine Gemeinschaft leidet bereits schwer unter der Dürre und der Notwendigkeit, den Forderungen des Zehntherrn nachzukommen. Wir müssen dennoch alle unseren Beitrag leisten.\n\nWir haben nur wenig Zeit, um diese Aufgabe zu erfüllen. Könnt Ihr helfen? Sammelt den Zehnt von den Dorfbewohnern und sucht das Gebiet nach jedem übersehenen Tropfen ab.", sourceObjective = "Sammelt Anima im Dorf für den Zehnt.", completion = "Ich war nicht sicher, ob dieser Auftrag durchführbar war. Sehr beeindruckende Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[60177] = { id = 60177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anlass für den Verrat", description = "Wenn Ihr mich fragt, ist der Angriff auf unsere Karawane verdächtig. Ich habe Herrin Mihaela gesagt, dass es einen Verräter im Dorf geben muss, aber es kümmert sie nicht. Das ist verständlich. Sie muss sich den Kopf darüber zerbrechen, einen neuen Zehnt zusammenzubringen.\n\nIch habe es auf mich genommen, dies zu klären, und ich könnte Eure Hilfe brauchen. Ich stelle diskrete Nachforschungen an, aber man darf nicht sehen, wie ich mit dem Personal spreche. Da kommt Ihr ins Spiel. Ihr könnt <mein investigativer Assistent/meine investigative Assistentin> sein.", sourceObjective = "Sprecht mit der \"Haushaltshilfe\" im Dorf, um Hinweise auf die Identität des Verräters zu finden.", progress = "Habt Ihr den Verräter bereits entlarven können?", completion = "Na, das sind ja interessante Informationen, die Ihr da ausgegraben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[60178] = { id = 60178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und dann war da keiner mehr", description = "Ilka und Samu haben sich gestritten, sagt Ihr? Und Ihr habt eine verschlüsselte Nachricht gefunden, die darauf hinweist, dass der Zehnt bald fortgebracht werden sollte. Das sind hilfreiche Anhaltspunkte, mit denen ich das Puzzle zusammensetzen kann.\n\nMir ist jetzt klar, wer das Dorf verraten hat und was wir dagegen tun müssen! Ihr überbringt unseren Verdächtigen eine Einladung zu einem Treffen und ich bereite alles vor, um den Verräter zu entlarven.", sourceObjective = "Versammelt die Verdächtigen und trefft Euch mit Lajos in der großen Gruft.", progress = "Der Meister weiß, was das Beste für uns ist. Wir müssen unseren Beitrag leisten.", completion = "Schön, dass am Ende alles geklappt hat. Danke für die unbeabsichtigte Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[60179] = { id = 60179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrende Erinnerung", description = "<Eine Tafel ist in den Boden neben den zur Schau gestellten Überresten einer Rüstung eingelassen.\n\nDie Runen der Inschrift erwecken Bilder eines uralten Kriegers vor Eurem geistigen Auge. Maldraxxus ehrt offensichtlich die Geschichte derer, die hier große Siege errungen haben.\n\nÄhnliche Gedenkstätten scheinen über den Graben verteilt zu sein. Vielleicht bieten sie mehr Informationen über die Bewohner dieses Reichs.>", sourceObjective = "Lest 3 verblasste Inschriften.", completion = "In Maldraxxus streben viele nach Größe. Nur wenigen wird wirklich Ruhm zuteil.\n\nLasst uns sehen, ob man sich eines Tages an unsere Namen erinnern wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[60180] = { id = 60180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reflexion eines Paragons", description = "<Der Kammerhüter studiert Euch.>\n\nIhr scheint eine einzigartige Signatur zu tragen, die eindeutig einem der Paragons zuzuordnen ist. Wenn Ihr wisst, zu welchem Paragon sie gehört, schaut einfach in den Seelenspiegel, um die Erinnerung Eurer Wahl zu untersuchen.\n\nWenn Ihr noch etwas benötigt, dann sprecht es einfach aus.", sourceObjective = "Offenbart die letzte Erinnerung.", progress = "Habt Ihr die gesuchte Erinnerung gefunden?", completion = "Ich hoffe, Eure Erfahrung war zufriedenstellend.", sourceObjectiveStatus = "unverified-source-field" }
quests[60181] = { id = 60181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabenkämpfe", description = "Diese Möchtegernrekruten wollen sich beweisen. Geben wir ihnen die Möglichkeit.\n\nDas Gespenst Malifis ist stärker geworden, weil es unsere Animavorräte aufgezehrt hat. In diesen Zeiten der Dürre können wir es uns nicht leisten, unsere wichtigste Ressource zu verlieren.\n\nWir müssen uns sofort um diese Bedrohung kümmern.\n\nBenutzt dieses Horn, um die rekrutierten Plünderer zu rufen. Sehen wir, wie gut sie sich unter unserem Banner schlagen!", sourceObjective = "Benutzt das Kriegshorn des Barons, um Malifis zu besiegen.", completion = "Eine Bedrohung für das Haus der Auserwählten beseitigt, und neue Rekruten, die Potenzial zeigen.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[60182] = { id = 60182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmausender Seelenfresser" }
quests[60183] = { id = 60183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterher!", description = "Wir müssen uns beeilen! Die Anima wird der Schlüssel dazu sein, diese Bürger für den bevorstehenden Kampf zu stärken.\n\nTodesreißer ist bereit zur Abreise.", sourceObjective = "Klettert auf Todesreißer und reitet mit Baronin Draka, um die Kutsche aufzuhalten.", completion = "Eine herrliche Zurschaustellung der Stärke von Sündensturz, {name}. \n\nSollen wir fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[60184] = { id = 60184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ey Mann, wo is' meine Nekropole?", description = "Das Portal zwischen unserem Sanktum und der Zerekriss aufrechtzuerhalten, ist schwer. Wir könnten es mit genug Ressourcen dauerhaft offenhalten und zu der unaufhaltsamen Macht werden, die meine Baronin gerne sehen würde.\n\nSie hat viel von Euch verlangt, und ich auch. Aber diese Anstrengung wird Euren Namen zur Legende unter den Maldraxxi machen, so wie der meiner Baronin einer geworden ist.\n\nHelft dabei, uns zu ermächtigen, und Ihr werdet im Gegenzug ermächtigt.", sourceObjective = "Wertet das Portalsystem Eures Sanktums auf Stufe 2 auf.", completion = "Ihr beeindruckt mich immer mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[60185] = { id = 60185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Ny'alotha Raid Finder - 1st" }
quests[60188] = { id = 60188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen überschreiten!", description = "Ah, Ihr kommt gerade recht. Ich habe eine aufregende Entdeckung gemacht.\n\nEs ist mir gelungen, eine Verbindung über eine Entfernung herzustellen, die ich noch nie zuvor erreicht habe.\n\nIhr wollt wissen, wie ich das gemacht habe? Mit harter Arbeit! Aber das wusstet Ihr bereits. Ihr arbeitet fast so hart wie ich. Genau deswegen seid Ihr hier!\n\nSeid Ihr bereit für ein noch aufregenderes Abenteuer?", sourceObjective = "Untersucht das unbekannte Gebiet.", progress = "Ich spüre einen Luftzug auf der anderen Seite. Das wird wohl bedeuten, dass es nicht unterirdisch ist.", completion = "Das war wirklich nett von Euch. Nicht viele Leute kümmern sich um uns Ältere hier.\n\nSie hat Euch sogar Seide gegeben! Wie nett. Hier, warum behaltet Ihr sie nicht? Ich brauche sie ganz bestimmt nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[60189] = { id = 60189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir schlagen jetzt zu", description = "Es ist soweit. Die Wilde Jagd hat die Drust wieder in ihre Hochburg am Rande des Ardenwalds zurückgedrängt.\n\nIhre Späher berichten, dass Gorak Zhar höchstpersönlich unter ihnen ist. Dies könnte unsere einzige Gelegenheit sein, die Diener von Thros in diesem Reich auszumerzen.\n\nLord Herne erwartet Eure Ankunft an der Front. Sputet Euch, {name}.", sourceObjective = "Trefft Lord Herne außerhalb des Dunkelvorstoßes.", completion = "Gut. Ihr seid da.\n\nJetzt sind wir bereit, die Drustinvasion ein für alle Mal zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[60190] = { id = 60190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Dunkelvorstoß", description = "Die Drust haben diesem Wald und seinen Bewohnern große Verluste zugefügt, {name}. Es ist Zeit, dass wir ihren Gräueltaten ein Ende bereiten.\n\nWir werden die Drust aus ihrer Enklave vertreiben und ihr Tor in den Ardenwald schließen. Mit Euch als Vorhut ist uns der Sieg sicher.\n\nIch werde mich mitten ins Herz ihres Lagers begeben. Sucht mich auf, sobald Ihr ihre Streitkräfte in die Flucht geschlagen habt.", sourceObjective = "Greift die Streitkräfte der Drust im Dunkelvorstoß an.", completion = "Gut gekämpft. Die Wilde Jagd wird sich nach Bedarf um den Rest kümmern. Aber wir müssen noch einen weiteren Gegner bezwingen.\n\nSeid Ihr vorbereitet?", sourceObjectiveStatus = "unverified-source-field" }
quests[60191] = { id = 60191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingra Drif", description = "Ingra Drif, der Hauptmann der Drust, wurde im Dunkelvorstoß gesichtet. Das ist unsere Chance, ihn für immer zu vernichten.\n\nIch kenne ihn und seine Grausamkeit nur zu gut, {name}. Was auch immer Ihr ihm antut, es ist besser als das, was er verdient.", sourceObjective = "Tötet Ingra Drif.", completion = "Gut. Die Drust haben einen schweren Rückschlag erlitten.\n\nDie Geister derjenigen, die wir durch den Verrat von Ingra Drif verloren haben, können endlich in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60192] = { id = 60192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre letzte Verteidigungslinie", description = "Diese hinterhältigen Drust beschützen Gorak Zhar mit ihrer bösen Magie!\n\nIch kann mehrere widerwärtige Runen spüren, die überall im Dunkelvorstoß verstreut sind. Wenn Ihr sie zerstört, können wir die Barriere um diese fiese Gorak Zhar mit Leichtigkeit niederreißen.\n\nBeeilt Euch! Ich treffe Euch im gegnerischen Lager.", sourceObjective = "Zerstört Gorak Zhars Schildrunen.", completion = "Ha! Jetzt hat sie keinen Schutz mehr. Bringen wir es zu Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[60193] = { id = 60193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demaskiert", description = "Dank Eurer Bemühungen ist der Schild, der unsere Beute schützt, jetzt so brüchig wie ein ausgetrocknetes Blatt.\n\nUnsere Jagd ist so gut wie abgeschlossen.\n\nKommt, lasst uns dieser niederträchtigen Gorak Zhar ein Ende bereiten.", sourceObjective = "Tötet Gorak Zhar.", completion = "Oh, Ara'lon... Selbst nach allem, was er durchgemacht hatte, fand er einen Weg, wieder zu lächeln... nur um....\n\n<Lady Mondbeere wischt sich über die Augen.>\n\nSpäter wird Zeit für Tränen sein. Wir müssen die Drust immer noch aufhalten. Für Ara'lon... und den Wald, für dessen Schutz er gekämpft hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[60194] = { id = 60194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Jagd", description = "Ich befürchte, Lord Herne wird erneut unsere Hilfe benötigen, bevor der Morgen anbricht.\n\nKommt, ich verleihe Euch Flügel. Wir müssen fliegen, um mit ihm Schritt zu halten.", sourceObjective = "Sprecht mit Lord Herne im Ardenwald.", completion = "Die Drust sollen verflucht sein! Das war alles eine Ablenkung!", sourceObjectiveStatus = "unverified-source-field" }
quests[60195] = { id = 60195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eins bauen", description = "All diese Seelen verdienen ein neues Konstrukt, und wenn sie neu gebaut werden, sind sie eine wertvolle Ergänzung unserer Streitkräfte.\n\nIrgendwo müssen wir anfangen.\n\nIhr solltet überall in den Schattenlanden formbares Fleisch finden können. Einige andere Teile dürften schwieriger aufzutreiben sein.\n\nSammelt Teile und benutzt den Tisch für Monstrositätenflickerei, um ein neues Konstrukt zu bauen.", sourceObjective = "Baut ein neues Konstrukt.", completion = "So viele mächtige Seelen! Diese Neuzugänge werden unsere Streitkräfte ordentlich verstärken!", sourceObjectiveStatus = "unverified-source-field" }
quests[60211] = { id = 60211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporen um die Ohren" }
quests[60215] = { id = 60215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torknacker zur rechten Zeit", description = "Habt Ihr die gigantische mechanische Monstrosität gesehen, die einfach zwischen den Dünen draußen umherläuft? Und wie sieht es mit dem Sha des Zorns aus? Oder dem großen Frostriesen im Norden? Ja, die sind in diesem Gebiet nicht einheimisch.\n\nSie haben mir gesagt, dass die Zeitwege zu dieser Zeit des Jahres etwas durcheinander sind. Deshalb haben sie mich auch darum gebeten, eine Truppe für eine Aufräumaktion zusammenzustellen.\n\nWärt Ihr für diese Herausforderung zu begeistern? Wenn Euch diese Herausforderung gefällt, habe ich auch noch eine andere für Euch.", sourceObjective = "Besiegt den Verdammniswandler, das Sha des Zorns und Archavon den Steinwächter in Tanaris.", progress = "Wie läuft's?", completion = "Danke, dass Ihr Verdammniswandler zur Strecke gebracht habt. Hoffen wir, dass das nicht noch mal passiert! Aber das wird es!", sourceObjectiveStatus = "unverified-source-field" }
quests[60217] = { id = 60217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60218] = { id = 60218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60219] = { id = 60219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60220] = { id = 60220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60221] = { id = 60221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
