quests[60229] = { id = 60229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60230] = { id = 60230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto besser", description = "Unsere Arbeit hier spricht sich herum. Es sind neue Seelen eingetroffen, die sich uns anschließen wollen!\n\nNehmt ihre Anfragen für neue Konstruktkörper entgegen. Vielleicht können wir auch für sie neue Konstrukte bauen!", sourceObjective = "Nehmt die Anfragen von den anwesenden Seelen entgegen.", completion = "So viele Seelen, es gibt so viel zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[60231] = { id = 60231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustand des Verfalls" }
quests[60236] = { id = 60236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückmeldung: Grufthüter Kassir", description = "Es wäre mir eine große Ehre, am Gluthof von Prinz Renathal teilnehmen zu dürfen.\n\nBei solch prestigereichen Anlässen bevorzuge ich es, meinen offiziellen Siegelring zu tragen. Ich erhielt ihn von der Anklägerin selbst, als mir meine ersten Pflichten zugewiesen wurden.\n\nAber leider haben die Schergen des Obersten Kämmerers ihn wieder einmal gestohlen.\n\nSie verstecken ihre unlauter erworbenen Besitztümer in diesen Gruften... Leider weiß ich nicht, in welcher sich mein Ring befindet.\n\nEs könnte eine Weile dauern, diese Sühnengruftschlüssel zu finden, aber alle Venthyr hier könnten einen davon haben.", sourceObjective = "Sammelt Sühnengruftschlüssel von den Venthyr in den Hallen der Sühne und öffnet Sühnengruften, bis Ihr den verlorenen Grufthüterring gefunden habt.", progress = "Begehrte Objekte finden sich oftmals an den unwahrscheinlichsten Orten, nicht wahr? Vielleicht haben wir dieses Mal ja Glück.", completion = "Ich bin Euch überaus dankbar, Schlundgänger!\n\n<Der Grufthüter steckt den Ring in seine Tasche und klopft vergewissernd darauf.>\n\nJetzt kann ich dem Gluthof in meinem besten Aufzug beiwohnen.\n\nIch hoffe, dass die Anklägerin dort Rituale ausführen wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[60237] = { id = 60237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das alte Revier", description = "Einmal, vor langer Zeit, bin ich in den Ardenwald gereist, um bei der Beseitigung einer jetzt längst vergessenen Bedrohung zu helfen.\n\nIch weiß noch, dass ich dort kleine Kreaturen gesehen habe, die winzige Anhäufungen von Anima gesammelt und im Erdreich vergraben haben. Die Fae nannten diese Objekte Animazapfen.\n\nWenn diese Anhäufungen noch da sind, müssen wir sie für uns sichern!\n\nIch sollte jeden Animazapfen, über den wir stolpern, ausgraben können. Lasst uns Jagd auf sie machen!", sourceObjective = "Sammelt 15 verlorene Animazapfen. Benutzt Zahnstochers Weltenschüttler, um sie auszugraben.", completion = "Habt Dank, Schlundgänger. Diese zusätzliche Anima wird für unsere Bemühungen enorm hilfreich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[60238] = { id = 60238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[60239] = { id = 60239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[60242] = { id = 60242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Nekrotische Schneise", description = "Wir Mittler messen Dingen Wert bei, die Fremdlingen wie Euch seltsam vorkommen könnten. Wir schätzen ungewöhnliche und einzigartige Objekten mehr als andere.\n\nWie wär es also mit einem Geschäft, hm? Solltet Ihr ein solches Objekt besitzen, biete ich Euch einen Handel gegen etwas an, das für Euch mehr Wert hat.\n\nWie ich höre, haben die Truppen von Maldraxxus die Bastion angegriffen. Und bei solchen Vorkommnissen spielen doch immer auch mächtige Objekte eine Rolle, oder?", sourceObjective = "Beschafft Nalthors Phylakteriumanleitung von Nalthor dem Eisbinder in der Nekrotischen Schneise.", progress = "Habt Ihr irgendwelche interessanten Objekte gefunden?", completion = "Ah, ein guter Fund. Wir erhalten nur selten einen Einblick in die Mechanismen, mithilfe derer das Haus der Rituale seine dunklen Entwicklungen ausführt. Ich bin schon sehr gespannt auf die Lektüre dieses Folianten, aus rein wissenschaftlicher Neugierde, versteht sich.\n\nIhr könnt ein paar Gegenstände aus unserem Bestand als Belohnung auswählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60243] = { id = 60243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Die Blutigen Tiefen", description = "Die Generäle von Revendreth sind mit feinsten Waffen und Rüstungen ausgestattet, die von Graf Denathrius in seinem unstillbaren Hunger nach Macht bereitgestellt wurden. Was profitable Geschäfte und Händel betrifft, hat er uns teilweise übervorteilt.\n\nEs wäre mir eine große Freude, wenn ein paar der Dinge, die ihm mehr Vorteile als uns verschafft haben, zurückgebracht werden könnten. Es gibt nur wenig, das für meinesgleichen demütigender wäre.", sourceObjective = "Beschafft ein Medaillon der Orientierung von Generalin Kaal in den Blutigen Tiefen.", progress = "Was habt Ihr mir mitgebracht?", completion = "Ja, das ist genau, wovon ich gesprochen habe. Die törichten Generäle von Revendreth haben dieses Medaillon zur Orientierung auf Reisen in fremden Gebieten benutzt, aber ihre Ambitionen waren beschränkt.\n\nFür meine Leute, die bis jenseits der bekannten Länder gereist sind, ist ein solches Objekt von unschätzbarem Wert, wenn sie versuchen, einen Rückweg festzulegen.\n\nWir haben dafür wertvolle Verwendung und es ist gut, dass Ihr es zurückgebracht habt. Hier ist eine Belohnung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[60244] = { id = 60244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Hallen der Sühne", description = "Die Mechanismen, mithilfe derer die jeweiligen Länder der Schattenlande geführt werden, sind wahrlich faszinierend. Doch ich hatte immer ein besonderes Interesse an den Venthyr von Revendreth.\n\nWie sie den Seelen ihre Sünden entziehen, sie in seltsamen Steinen verwahren und Diener aus dem Dreck schaffen, der sie umgibt. Das alles ist sehr eigentümlich.\n\nAber sie behalten ihre Geheimnisse für sich und geben kaum Informationen preis. Ich biete einen Handel für jegliche ihrer Folianten an, derer Ihr habhaft werden könnt.", sourceObjective = "Beschafft den Folianten der Gräberalchemie vom Obersten Kämmerer in den Hallen der Sühne.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Ein Foliant aus Revendreth? Ja, lasst mich mal sehen.\n\nEr enthält alchemistische Formeln zur Erschaffung der Gräberbecken sowie verschiedene Anleitungen zur Erschaffung und Verwendung der kleinen Kreaturen. Sie sind echte Kuriositäten, gleichsam Diener wie Reagenz.\n\nDafür biete ich Euch mit Freuden einen guten Handel an. Hier, bitte wählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[60245] = { id = 60245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Die Andre Seite", description = "Mueh'zala ist eine uralte und primitive Kreatur, die über einen Ort herrscht, den man \"Die Andre Seite\" nennt. Über dieses Land ist nur wenig bekannt, denn es ist uns nicht erlaubt, es zu besuchen. Wir haben viele Handelsangebote ausgesendet, aber nie eine Antwort erhalten.\n\nDas ist eine Schande, denn die wenigen, die Mueh'zalas Klauen entkommen konnten, berichteten, dass sein Reich ein Ort voller seltsamer Dinge ist.\n\nWir würden Euch natürlich nie darum bitten, einen solch gefährlichen Ort aufzusuchen. Andererseits gibt es ein verbindliches Angebot für Dinge aus Mueh'zalas Besitz.", sourceObjective = "Beschafft eine goldene Totenmaske von Mueh'zala auf der Andren Seite.", progress = "Euch haftet der Gestank des Todes an.", completion = "Oh, ein großartiger Fund, nicht wahr? Etwas von der Andren Seite. Wir bekommen solche Dinge nur sehr selten zu Gesicht, also werde ich sie gleich untersuchen. Sie scheint von einem vergessenen, primitiven Volk zu stammen, das Mueh'zala angebetet hat.\n\nDies verlangt natürlich nach einer Belohnung. Trefft Eure Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[60246] = { id = 60246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Tirna Scithe", description = "Wenn man sie lässt, verschlingen die Gorm alles auf ihrem Weg. Wir haben schon so einige von ihnen sowohl als Haustiere als auch als Waffen verkauft. Ihr würdet wahrscheinlich lieber nicht mitansehen wollen, wenn sie auf eine Welt losgelassen werden, um sich dort einzunisten.\n\nOder vielleicht doch? Einige Leute halten das für Unterhaltung.\n\nZurzeit ist es schwer für uns, den Ardenwald zu erkunden, wenn er von solchen Dingen bevölkert wird. Eine fette, gesunde Gormlarve bringt einen schönen Preis auf dem Markt. Ich glaube, wir verstehen uns, oder?", sourceObjective = "Beschafft eine vollgefressene Gormlarve von Tred'ova in den Nebeln von Tirna Scithe.", progress = "Habt Ihr die Aufgabe abgeschlossen?", completion = "Oh, was ist das denn? Die ist so prall und windet sich so stark, sie muss kurz vor der nächsten Häutung sein. Ich bin selbst ein Amateurgormzüchter und werde einen angemessenen Ort für sie finden, um sie großzuziehen.\n\nIch gebe Euch mein Wort, dass Ihr Euch darauf verlassen könnt, dass ich keine Welten vernichten will.\n\nUnd jetzt muss ich mich um sie kümmern. Nehmt Euch auf dem Weg nach draußen etwas aus unseren Vorräten.", sourceObjectiveStatus = "unverified-source-field" }
quests[60247] = { id = 60247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Theater der Schmerzen", description = "Großmeister Vole betreibt die Arena in Maldraxxus, wo die Champions der Häuser um Ruhm und Ehre kämpfen. Natürlich erhalten die Gewinner auch häufig Preise.\n\nWir selbst nehmen nicht häufig an solchen Kämpfen teil. Einen solchen Preis in unserem Angebotsportfolio zu finden wäre also äußerst ungewöhnlich.\n\nMuss ich noch deutlicher werden? Wenn wir dieses Geschäft im Stillen zwischen uns abwickeln können, trenne ich mich gern von ein paar wertvollen Waren.", sourceObjective = "Beschafft eine Münze des Champions von Mordretha im Theater der Schmerzen.", progress = "Sechs, sieben, acht... Oh, ja, bitte? Habt Ihr einen Handel anzubieten? Ich habe noch viel mehr Inventar im Angebot.", completion = "Interessanterweise werden diese Münzen den Champions der Arena von Maldraxxus nur dann verliehen, wenn sie einige Zeit dort gedient haben. Sie sind rein zeremonieller Art und für die meisten Leute ohne Wert. Umso mehr aber für jene, die Zeremonien schätzen.\n\nBitte nehmt Euch etwas als Entschädigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[60248] = { id = 60248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Seuchensturz", description = "Es ist eine Schande, was der armen Markgräfin Stradama widerfahren ist. Ganz unter uns: Sie war einst eine unserer höchst geschätzten Handelspartner. Dinge, die in Maldraxxus verloren gehen, finden sich üblicherweise am Grund Ihrer verseuchten Teiche wieder.\n\nIhr hättet nicht vielleicht Interesse daran, unsere Handelsbeziehung an ihrer Statt fortzusetzen? Wir würden uns dafür natürlich angemessen erkenntlich zeigen.\n\nIch bin mir sicher, dass sie in ihrem gegenwärtigen Zustand wenig Verwendung für diese Dinge hat.", sourceObjective = "Beschafft eines von Stradamas verschwundenen Geschäftsbüchern von Markgräfin Stradama in Seuchensturz.", progress = "Oh, Ihr seid es wieder.", completion = "Oh, du meine Güte, das nenne ich mal einen Fund. Dieser Katalog führt einige von Stradamas Objekten auf, die sie in ihren Seuchenteichen verborgen hat. Dafür haben wir zweifellos gute Verwendung.\n\nBitte wählt etwas aus, das Euch gefällt. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[60249] = { id = 60249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handel und Wandel: Spitzen des Aufstiegs", description = "Die Kyrianer der Bastion nehmen eine einzigartige Rolle in den Schattenlanden ein, weil sie die sterblichen Seelen von ihren Reichen in unsere überführen. Es scheint, dass sie dies in Zeiten der Krise oder Verwüstung in großer Zahl bewerkstelligen können.\n\nWir würden gern mehr über ihre Reisen in die jenseitigen Reiche erfahren.\n\nEiner von ihnen hat doch bestimmt etwas aus einem anderen Land mitgebracht? Sie sind doch immer so interessiert an Erinnerungen.", sourceObjective = "Beschafft eine seltsame Puppe von Devos, Paragon des Zweifels, in den Spitzen des Aufstiegs.", progress = "Wie kann ich Euch helfen?", completion = "Ein seltsames Spielzeug, wahrscheinlich aus einer anderen Welt. Aber warum hätte das Paragon so etwas an sich nehmen sollen?\n\nVielleicht hat es die Seele eines Kindes überführt und dies hat sie etwas erinnert, was für sie selbst verloren ist? Ich werde darüber nachdenken.\n\nIhr könnt eine Belohnung aus unseren Vorräten wählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60250] = { id = 60250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Theater der Schmerzen", description = "Das Theater der Schmerzen in Maldraxxus ist ein brutaler Ort, an dem nur die Stärksten überleben.\n\nDa die Häuser untereinander in solch hartem Wettkampf stehen, ist es ihr ganzer Stolz, dort einen siegreichen Champion hervorzubringen.\n\nAus diesem Grund statten die Oberhäupter der Häuser ihre Kämpfer oft mit mächtigen Waffen, Rüstungen und Accessoires aus. Dazu gehören auch geschichtsträchtige Gegenstände, die von Schlacht zu Schlacht weitergereicht wurden.\n\nEinen solchen Gegenstand würde ich mir gern einmal anschauen.", sourceObjective = "Beschafft einen Ring aus fremdartigen Metall von Mordretha im Theater der Schmerzen.", progress = "Wart Ihr siegreich oder seid Ihr gekommen, um Eure Wunden zu pflegen?", completion = "Diese Narren verschwenden ein solches Objekt als bloßes Accessoire für den Einsatz in Kämpfen. Wissen sie etwa nicht um seine Bedeutung? Offensichtlich nicht.\n\nLasst es mich erklären.\n\nEs gibt vieles, das wir nicht über diese Welt wissen. Diese Stadt, Oribos, ist aus einem seltsamen Erz erbaut, das wir nirgendwo anders gefunden haben. Wer hat diesen Ort erbaut, und warum?\n\nRelikte dieser Art sind alles, was wir haben, um dieses Mysterium zu entwirren.\n\nWir danken Euch für dieses Geschenk. Bitte nehmt Euch einen der Schätze.", sourceObjectiveStatus = "unverified-source-field" }
quests[60251] = { id = 60251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Seuchensturz", description = "Das Leben in Maldraxxus ist ein fortwährender Kampf, ein ewiger Wettstreit unter den Häusern. Und von Zeit zu Zeit kann das Oberhaupt eines Hauses Besitz von Gegenständen oder Wissen erlangen, das so selten ist, dass daraus ein entscheidender Vorteil resultiert.\n\nEs ist möglich, oder sogar wahrscheinlich, dass ein solcher Umstand für das Schicksal des Hauses der Seuchen verantwortlich war.\n\nIch muss Euch nicht weiter verdeutlichen, wie wertvoll eine solche Rarität wäre, nicht wahr?", sourceObjective = "Beschafft eine schleimige Korrespondenz von Markgräfin Stradama in Seuchensturz.", progress = "Ja? Ich bin gerade sehr beschäftigt.", completion = "Ich kann nur wenige Worte dieses Schreibens entziffern. Gebt mir bitte einen Moment.\n\nEs scheint eine Warnung der Markgräfin zu sein, die sich an ein anderes Oberhaupt von Maldraxxus oder einen anderen Ort richtet.\n\nDer Primus und sein Schicksal finden Erwähnung. Oder das von jemand anderem? Schwer zu sagen. Es scheint auf einen Ort zu verweisen, aber ich verstehe die Beschreibung dieses Ortes nicht.\n\nDies könnte für das Schicksal der Schattenlande von größerer Bedeutung sein, als Ihr ahnt. Wählt eine Belohnung, ich werde meine Arbeit daran fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60252] = { id = 60252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Spitzen des Aufstiegs", description = "Ihr habt zweifelsohne die Bastion besucht und gesehen, was mit den Seelen geschieht, die dort angenommen werden. Ihre Erinnerungen werden entzogen, betrachtet und sogar im Tempel der Weisheit verwahrt.\n\nIn diesem Tempel befinden sich somit Erinnerungen, die Antworten auf einige der größten Fragen über unser Reich und die jenseitigen Welten liefern könnten. Es ist eine Schande, dass sie nicht zugänglich sind.\n\nWir haben gehört, dass das gefallene Paragon der Loyalität ein Interesse an diesen Erinnerungen hat. Jede Erinnerung, die sein Interesse weckt, stellt also einen Handelswert dar.", sourceObjective = "Beschafft ein verblassendes Erinnerungsglas von Devos, Paragon des Zweifels, in den Spitzen des Aufstiegs.", progress = "Ihr seht aus, als hättet Ihr etwas mitzuteilen.", completion = "Dieses Erinnerungsglas ist sehr, sehr alt. Es könnte die Erinnerung einer Seele sein, die vor vielen Jahren übergewechselt ist, aber das lässt sich nicht mit Sicherheit sagen. Wir wissen aber, dass das enthaltene Wissen nicht reproduziert werden kann und schon bald verschwunden sein wird.\n\nIch werde mich sofort daran machen, so viel wie möglich davon zu sichern. Ich muss Euch jetzt bitten, zu gehen. Bitte nehmt Euch eine angemessene Belohnung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[60253] = { id = 60253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvoller Fund: Nekrotische Schneise", description = "Obschon es nicht oft vorkommt, erhalten wir von Zeit zu Zeit Objekte außergewöhnlich geheimnisvoller Herkunft. Diese Objekte gewähren uns einen kurzen Blick auf die Reiche jenseits unseres Verständnisses.\n\nEs mag Euch vorkommen, als spräche ich in Rätseln, aber selbst für uns stellen sich viele Dinge dieses Reiches noch als Mysterium dar.\n\nSchon andere haben versucht, die Geschichte dieses Reiches aufzudecken. Wenn Ihr also an eines ihrer Werke gelangen solltet, biete ich Euch einen für Euch äußerst lukrativen Handel an.", sourceObjective = "Beschafft \"Der Ursprung des Todes\" von Nalthor dem Eisbinder in der Nekrotischen Schneise.", progress = "Was habt Ihr entdeckt?", completion = "Was für eine Art Foliant ist das? Darf ich ihn kurz durchblättern?\n\nAlso, das ist ein kostbares Fundstück. Darin wird über viele Jahre vermerkt, was Nalthor über die Ursprünge unserer Welt herausgefunden hat. Die vielen Besonderheiten dieses Orts, von Zovaals Reich im Schlund bis zur Funktion dieser seltsamen Stadt, Oribos.\n\nDemnach scheint alles miteinander verbunden zu sein.\n\nIch werde das alles mit Freuden studieren. Kommt, Ihr dürft Euch dafür eines unserer wertvollsten Güter aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
